    public function __construct()
    {
        $this->middleware(function ($request, $next) {
            $user = Auth::user();

            if ($user && $user->isGuest()) {
                return redirect()->route('guest.free-tests')
                    ->with('error', 'Guest account does not have access to assignments.');
            }

            return $next($request);
        });
    }

