    public function ieltsListeningWarmUp($type)
    {
        $validTypes = ['spelling', 'times-dates', 'addresses', 'numbers', 'names', 'geographical-names', 'direction'];
        $practice = (int) request()->get('practice', 1);

        if (!in_array($type, $validTypes)) {
            abort(404);
        }

        // Create a dummy section object for the audio player partial
        $audioFiles = [
            'spelling' => 'audio/ielts/listening/warmup/spelling_practice_1.mp3',
            'times-dates' => 'audio/ielts/listening/warmup/times_dates_practice_1.mp3',
            'addresses' => 'audio/ielts/listening/warmup/addresses_practice_1.mp3',
            'numbers' => 'audio/ielts/listening/warmup/numbers_practice_1.mp3',
            'names' => 'audio/ielts/listening/warmup/names_practice_1.mp3',
            'geographical-names' => 'audio/ielts/listening/warmup/geographical_names_practice_1.mp3',
            'direction' => 'audio/ielts/listening/warmup/direction_practice_1.mp3',
        ];

        $titles = [
            'spelling' => 'Spelling Practice',
            'times-dates' => 'Times and Dates Practice',
            'addresses' => 'Addresses Practice',
            'numbers' => 'Numbers Practice',
            'names' => 'Names Practice',
            'geographical-names' => 'Geographical Names Practice',
            'direction' => 'Direction Practice',
        ];

        $descriptions = [
            'spelling' => 'Listen and type the words you hear.',
            'times-dates' => 'Listen and write down the times or time phrases you hear.',
            'addresses' => 'Listen and write down the addresses you hear.',
            'numbers' => 'Listen and write down the numbers (and letters) you hear.',
            'names' => 'Listen and write down the names you hear.',
            'geographical-names' => 'Listen and write down the geographical names you hear.',
            'direction' => 'Listen and write down the directions or location instructions you hear.',
        ];

        if ($type === 'names' && $practice === 2) {
            $practiceAudio = 'audio/ielts/listening/warmup/names_practice_2.mp3';
            $audioFiles['names'] = file_exists(public_path($practiceAudio)) ? $practiceAudio : $audioFiles['names'];
            $titles['names'] = 'Names Practice 2';
            $descriptions['names'] = 'Listen and tick the surnames you hear.';
        }

        $section = (object) [
            'audio_file' => $audioFiles[$type] ?? 'audio/ielts/listening/warmup/default.mp3',
            'transcript_en' => null,
            'transcript_id' => null,
            'title' => $titles[$type] ?? 'Practice',
            'description' => $descriptions[$type] ?? 'Listen to the audio.'
        ];

        return view('assignments.ielts.listening.warmup.' . $type, compact('section'));
    }

    public function uploadIeltsMaterialAudio(Request $request, $id)
    {
        $request->validate([
            'audio_file' => 'required|file|mimes:mp3,wav,ogg|max:51200',
        ]);

        $material = \App\Models\IeltsListeningMaterial::where('material_type_id', $id)->firstOrFail();

        if ($request->hasFile('audio_file')) {
            $file = $request->file('audio_file');
            $directory = "audio/ielts-academic/listening/material-{$id}";
            $publicPath = public_path($directory);
            
            if (!file_exists($publicPath)) {
                mkdir($publicPath, 0777, true);
            }

            $filename = 'audio_' . time() . '.' . $file->getClientOriginalExtension();
            $file->move($publicPath, $filename);

            // Delete old file
            if ($material->audio_file && file_exists(public_path($material->audio_file))) {
                @unlink(public_path($material->audio_file));
            }

            $material->update(['audio_file' => $directory . '/' . $filename]);

            return back()->with('success', 'Audio uploaded successfully.');
        }

        return back()->with('error', 'No file uploaded.');
    }

    public function uploadIeltsMaterialSrt(Request $request, $id)
    {
         $request->validate([
            'srt_file' => 'required_without:srt_content|nullable|file|extensions:srt|max:2048',
            'srt_content' => 'required_without:srt_file|nullable|string',
            'language' => 'required|in:en,id',
        ]);

        $material = \App\Models\IeltsListeningMaterial::where('material_type_id', $id)->firstOrFail();
        
        $content = '';
        if ($request->hasFile('srt_file')) {
            $content = file_get_contents($request->file('srt_file')->getRealPath());
        } else {
            $content = $request->input('srt_content');
        }

        if (!empty($content)) {
             $content = str_replace("\r\n", "\n", $content);
             $pattern = '/(\d+)\s+(\d{1,2}:\d{2}:\d{2}[,.]\d{1,3})\s*-->\s*(\d{1,2}:\d{2}:\d{2}[,.]\d{1,3})\s+([\s\S]*?)(?=(?:\n\s*\d+\s+\d{1,2}:\d{2}:\d{2})|$)/';
             
             $blocks = [];
             if (preg_match_all($pattern, $content, $matches, PREG_SET_ORDER)) {
                foreach ($matches as $match) {
                    $startTime = $this->srtTimeToSeconds($match[2]);
                    $endTime = $this->srtTimeToSeconds($match[3]);
                    $text = trim($match[4]);
                    $text = str_replace("\n", " ", $text);
                    
                    if (!empty($text)) {
                        $blocks[] = [
                            'start' => $startTime,
                            'end' => $endTime,
                            'text' => $text
                        ];
                    }
                }
             }
             
             $finalText = empty($blocks) ? $content : json_encode($blocks);
             
             // Determine column to update based on language
             $column = ($request->language === 'en') ? 'transcript_en' : 'transcript_id';
             $material->update([$column => $finalText]);
             
             return back()->with('success', 'Transcript uploaded/updated successfully.');
        }
        
        return back()->with('error', 'No content provided.');
    }

    public function uploadIeltsMaterialAnswerKey(Request $request, $id)
    {
        $request->validate([
            'answer_key' => 'required|string',
        ]);

        $material = \App\Models\IeltsListeningMaterial::where('material_type_id', $id)->firstOrFail();
        
        $material->update(['answer_key' => $request->answer_key]);

        return back()->with('success', 'Answer Key uploaded/updated successfully.');
    }

