    // IELTS Reading Passage CRUD
    public function storePassage(Request $request)
    {
        $validated = $request->validate([
            'material_id' => 'required|integer',
            'title' => 'required|string|max:255',
            'content' => 'required|string',
            'order' => 'nullable|integer'
        ]);

        $passage = \DB::table('ielts_reading_passages')->insert([
            'material_id' => $validated['material_id'],
            'title' => $validated['title'],
            'content' => $validated['content'],
            'order' => $validated['order'] ?? 0,
            'created_at' => now(),
            'updated_at' => now()
        ]);

        return response()->json(['success' => true, 'message' => 'Passage created successfully']);
    }

    public function updatePassage(Request $request, $id)
    {
        $validated = $request->validate([
            'title' => 'required|string|max:255',
            'content' => 'required|string',
            'order' => 'nullable|integer'
        ]);

        \DB::table('ielts_reading_passages')
            ->where('id', $id)
            ->update([
                'title' => $validated['title'],
                'content' => $validated['content'],
                'order' => $validated['order'] ?? 0,
                'updated_at' => now()
            ]);

        return response()->json(['success' => true, 'message' => 'Passage updated successfully']);
    }

    public function deletePassage($id)
    {
        \DB::table('ielts_reading_passages')->where('id', $id)->delete();
        return response()->json(['success' => true, 'message' => 'Passage deleted successfully']);
    }

    // IELTS Reading Question CRUD
    public function storeQuestion(Request $request)
    {
        $validated = $request->validate([
            'passage_id' => 'required|integer',
            'question_number' => 'required|integer',
            'question_text' => 'nullable|string',
            'type' => 'required|string',
            'options' => 'nullable|array',
            'correct_answer' => 'nullable',
            'explanation' => 'nullable|string',
            'order' => 'nullable|integer',
            'data' => 'nullable|array' // For extra fields like box_title, summary_text
        ]);

        \App\Models\IeltsReadingQuestion::create([
            'passage_id' => $validated['passage_id'],
            'question_number' => $validated['question_number'],
            'question_text' => $validated['question_text'], // Can be null
            'type' => $validated['type'],
            'options' => $validated['options'] ?? null, // Casted to array automatically by model
            'correct_answer' => $validated['correct_answer'] ?? null,
            'explanation' => $validated['explanation'] ?? null,
            'order' => $validated['order'] ?? 0,
            'data' => $validated['data'] ?? null
        ]);

        return response()->json(['success' => true, 'message' => 'Question created successfully']);
    }

    public function updateQuestion(Request $request, $id)
    {
        $validated = $request->validate([
            'question_number' => 'required',
            'question_text' => 'nullable|string',
            'type' => 'required|string',
            'options' => 'nullable|array',
            'correct_answer' => 'nullable',
            'explanation' => 'nullable|string',
            'order' => 'nullable|integer',
            'data' => 'nullable|array'
        ]);

        $question = \App\Models\IeltsReadingQuestion::findOrFail($id);
        $question->update([
            'question_number' => $validated['question_number'],
            'question_text' => $validated['question_text'],
            'type' => $validated['type'],
            'options' => $validated['options'] ?? null,
            'correct_answer' => $validated['correct_answer'] ?? null,
            'explanation' => $validated['explanation'] ?? null,
            'order' => $validated['order'] ?? 0,
            // 'data' => $validated['data'] ?? null
        ]);

        $data = $validated['data'] ?? [];
        // Ensure sub_questions is an array of objects (list) if it exists, to prevent {"0":...} object conversion
        if (isset($data['sub_questions']) && is_array($data['sub_questions'])) {
            $data['sub_questions'] = array_values($data['sub_questions']);
        }

        $question = \App\Models\IeltsReadingQuestion::findOrFail($id);
        $question->update([
            'question_number' => $validated['question_number'],
            'question_text' => $validated['question_text'],
            'type' => $validated['type'],
            'options' => $validated['options'] ?? null,
            'correct_answer' => $validated['correct_answer'] ?? null,
            'explanation' => $validated['explanation'] ?? null,
            'order' => $validated['order'] ?? 0,
            'data' => $data
        ]);

        return response()->json(['success' => true, 'message' => 'Question updated successfully']);
    }

