    public function uploadIeltsListeningAudio(Request $request, $meetingId, $set)
    {
        $user = Auth::user();
        if (!$user->isAdmin() && !$user->isTeacher()) {
            return redirect()->back()->with('error', 'Unauthorized access.');
        }

        $request->validate([
            'audio_file' => 'required|file|mimes:mp3,wav,m4a|max:51200',
        ]);

        if ($request->hasFile('audio_file')) {
            try {
                $file = $request->file('audio_file');
                
                // Create directory path
                $directory = "audio/ielts-listening/meeting-{$meetingId}/part-{$set}";
                $publicPath = public_path($directory);
                
                if (!file_exists($publicPath)) {
                    mkdir($publicPath, 0777, true);
                }
                
                $filename = 'audio_' . time() . '.' . $file->getClientOriginalExtension();
                $file->move($publicPath, $filename);
                $audioPath = $directory . '/' . $filename;

                // Update Section
                $section = \App\Models\IeltsSection::where('meeting_id', $meetingId)
                    ->where('section_number', $set)
                    ->first();
                    
                if($section) {
                    if ($section->audio_file && file_exists(public_path($section->audio_file))) {
                        @unlink(public_path($section->audio_file));
                    }
                    $section->update(['audio_file' => $audioPath]);
                } else {
                     return redirect()->back()->with('error', 'Section not found.');
                }

                return redirect()->back()->with('success', 'Audio uploaded successfully!');
            } catch (\Exception $e) {
                return redirect()->back()->with('error', 'Upload failed: ' . $e->getMessage());
            }
        }

        return redirect()->back()->with('error', 'No file uploaded.');
    }

    public function uploadIeltsListeningSrt(Request $request, $meetingId, $set)
    {
        $user = Auth::user();
        if (!$user->isAdmin() && !$user->isTeacher()) {
            return redirect()->back()->with('error', 'Unauthorized access.');
        }

        $section = \App\Models\IeltsSection::where('meeting_id', $meetingId)
            ->where('section_number', $set)
            ->first();

        if ($section) {
            $section->update([
                'transcript_en' => $request->input('transcript_en'),
                'transcript_id' => $request->input('transcript_id'),
            ]);
            return redirect()->back()->with('success', 'Transcripts updated successfully!');
        }

        return redirect()->back()->with('error', 'Section not found.');
    }

