    public function ieltsCambridgeTestTest($edition, $id, $skill = 'listening')
    {
        $uniqueTestId = $edition . str_pad($id, 2, '0', STR_PAD_LEFT);
        $material = \App\Models\IeltsListeningMockup::firstOrCreate(['test_id' => $uniqueTestId]);

        $validIds = [1, 2, 3, 4];
        if (!in_array((int)$id, $validIds)) {
            abort(404);
        }

        // Route by skill
        if ($skill === 'reading') {
            $editionReadingView = 'assignments.ielts.mockup.c' . $edition . '-reading-test-' . $id;
            $readingView = 'assignments.ielts.mockup.reading-test-' . $id;
            
            if (view()->exists($editionReadingView)) {
                return view($editionReadingView, ['edition' => $edition, 'testId' => $id]);
            } elseif (view()->exists($readingView)) {
                 return view($readingView, ['edition' => $edition, 'testId' => $id]);
            }
            abort(404);
        }

        if ($skill === 'writing') {
            $editionWritingView = 'assignments.ielts.mockup.c' . $edition . '-writing-test-' . $id;
            $writingView = 'assignments.ielts.mockup.writing-test-' . $id;
            
            if (view()->exists($editionWritingView)) {
                return view($editionWritingView, ['edition' => $edition, 'testId' => $id]);
            } elseif (view()->exists($writingView)) {
                 return view($writingView, ['edition' => $edition, 'testId' => $id]);
            }
            abort(404);
        }

        if ($skill === 'speaking') {
            $editionSpeakingView = 'assignments.ielts.mockup.c' . $edition . '-speaking-test-' . $id;
            $speakingView = 'assignments.ielts.mockup.speaking-test-' . $id;
            
            if (view()->exists($editionSpeakingView)) {
                return view($editionSpeakingView, ['edition' => $edition, 'testId' => $id]);
            } elseif (view()->exists($speakingView)) {
                 return view($speakingView, ['edition' => $edition, 'testId' => $id]);
            }
            abort(404);
        }

        // Default: listening
        $editionListeningView = 'assignments.ielts.mockup.c' . $edition . '-listening-test-' . $id;
        if (view()->exists($editionListeningView)) {
            return view($editionListeningView, ['edition' => $edition, 'testId' => $id, 'material' => $material]);
        }

        if ($id == 1) {
            return view('assignments.ielts.mockup.listening-test', ['edition' => $edition, 'testId' => $id, 'material' => $material]);
        } elseif ($id == 2) {
             return view('assignments.ielts.mockup.listening-test-2', ['edition' => $edition, 'testId' => $id, 'material' => $material]);
        } elseif ($id == 3) {
             return view('assignments.ielts.mockup.listening-test-3', ['edition' => $edition, 'testId' => $id, 'material' => $material]);
        } elseif ($id == 4) {
             return view('assignments.ielts.mockup.listening-test-4', ['edition' => $edition, 'testId' => $id, 'material' => $material]);
        }
        
        abort(404);
    }

