    {
        $request->validate([
            'audio_file' => 'required|file|mimes:mp3,wav,ogg|max:51200',
        ]);

        $uniqueTestId = $edition . str_pad($id, 2, '0', STR_PAD_LEFT);
        $material = \App\Models\IeltsListeningMockup::firstOrCreate(['test_id' => $uniqueTestId]);

        if ($request->hasFile('audio_file')) {
