    public function upgradeSpeakingLexical(Request $request)
    {
        sleep(1); 
        $transcripts = $request->input('transcripts', []);
        $topic = $request->input('topic', 'general');
        
        // Flatten transcripts to find words
        $fullText = '';
        foreach ($transcripts as $t) {
            $fullText .= strtolower($t['answer'] ?? '') . ' ';
        }

        $vocabMap = $this->getAdvancedVocabForTopic($topic);
        $improvements = [];

        foreach ($vocabMap as $simple => $data) {
            // Simple check if word exists in text
            if (str_contains($fullText, " $simple ") || str_contains($fullText, " $simple.") || str_contains($fullText, " $simple,")) {
                $improvements[] = [
                    'original' => $simple,
                    'improved' => $data[0],
                    'explanation' => $data[1]
                ];
            }
        }

        // If no matches found, suggest top 3 topic words anyway
        if (empty($improvements)) {
             $count = 0;
             foreach ($vocabMap as $simple => $data) {
                 // Skip common ones if possible if we found topic match, but here just take first few
                 $improvements[] = [
                    'original' => $simple,
                    'improved' => $data[0],
                    'explanation' => '(Saran) ' . $data[1]
                ];
                $count++;
                if ($count >= 5) break; 
             }
        }

        return response()->json([
            'status' => 'success',
            'improvements' => array_slice($improvements, 0, 5) // Limit to 5
        ]);
    }



    public function suggestSpeakingCollocations(Request $request)
    {
        sleep(1); 
        $topic = $request->input('topic', 'general'); // e.g. 'work-or-studies', 'technology'
        
        $collocationsRaw = $this->getCollocationsForTopic($topic);
        $idiomsRaw = $this->getIdiomsForTopic($topic);

        $suggestions = [];

        // Format Idioms
        foreach ($idiomsRaw as $item) {
            $suggestions[] = [
                'term' => $item['phrase'],
                'type' => 'Idiom',
                'definition' => $item['meaning'],
                'example' => $item['example']
            ];
        }

        // Format Collocations
        foreach ($collocationsRaw as $item) {
            $suggestions[] = [
                'term' => $item['phrase'],
                'type' => 'Collocation',
                'definition' => $item['meaning'],
                'example' => $item['example']
            ];
        }

        return response()->json([
            'status' => 'success',
            'collocations' => $suggestions // Frontend uses 'collocations' key
        ]);
    }

