    public function upgradeSpeakingGrammar(Request $request)
    {
        sleep(1);

        $transcripts = $request->input('transcripts', []);
        $topic = $request->input('topic', 'general');
        
        // Simple mock context detection
        $isWork = stripos(json_encode($transcripts), 'work') !== false || stripos($topic, 'work') !== false;
        $isStudy = stripos(json_encode($transcripts), 'study') !== false || stripos($topic, 'study') !== false;

        // Detect specific question patterns to generate "Answer-like" upgrades
        $questionsText = '';
        foreach ($transcripts as $t) {
            $questionsText .= strtolower($t['question'] ?? '') . ' ';
        }
        
        $upgrades = [];

        if (str_contains($questionsText, 'dislike')) {
             $upgrades = [
                [
