    public function readingMeeting($number)
    {
        $meeting = \App\Models\ToeflReadingMeeting::where('meeting_number', $number)->firstOrFail();

        // Check Lock
        $batchLockMap = collect();
        $selectedClassPeriod = $this->resolveToeflSelectedClassPeriod(Auth::user());
        if ($selectedClassPeriod) {
            $batchLockMap = \App\Models\ClassPeriodToeflMeeting::where('class_period_id', $selectedClassPeriod->id)
                ->where('module', 'reading')
                ->pluck('is_open', 'meeting_number');
        }
        $isLocked = $this->resolveToeflLockedState($batchLockMap, (int) $meeting->meeting_number, (bool) $meeting->is_locked, (bool) $selectedClassPeriod);
        if ($isLocked) {
            return redirect()->route('assignments.toefl-itp.reading')->with('error', 'Class is locked.');
        }

        // Load Passages and Questions
        $allPassages = \App\Models\ToeflReadingPassage::where('meeting_id', $meeting->id)
            ->with(['questions' => function($q) {
                $q->orderBy('question_number');
            }])
            ->orderBy('passage_number')
            ->get();

        // Custom view for Meeting 13
        if ($number == 13) {
            return view('assignments.toefl-itp.reading.meeting13', [
                'meeting' => $meeting,
                'passages' => $allPassages
            ]);
        }

        // Always show meeting view with all passages
        return view('assignments.toefl-itp.reading.meeting', [
            'meeting' => $meeting,
            'passages' => $allPassages
        ]);
    }

    public function structureMeeting($number)
    {
        $meeting = \App\Models\ToeflStructureMeeting::where('meeting_number', $number)->firstOrFail();

        // Check Lock
        $batchLockMap = collect();
        $selectedClassPeriod = $this->resolveToeflSelectedClassPeriod(Auth::user());
        if ($selectedClassPeriod) {
            $batchLockMap = \App\Models\ClassPeriodToeflMeeting::where('class_period_id', $selectedClassPeriod->id)
                ->where('module', 'structure')
                ->pluck('is_open', 'meeting_number');
        }
        $isLocked = $this->resolveToeflLockedState($batchLockMap, (int) $meeting->meeting_number, (bool) $meeting->is_locked, (bool) $selectedClassPeriod);
        if ($isLocked) {
            return redirect()->route('assignments.toefl-itp.structure')->with('error', 'Class is locked.');
        }

        // Check is it a "Main" meeting (standard lesson) or a "Sub" meeting (exercise > 50)?
        // If it's a sub-meeting (e.g. 62), we just show it directly (it's the exercise itself).
        // If it's a main meeting (e.g. 1-12) AND we don't have '?exercise=1', we apply Selection Mode.
        if ($number < 50 && !request()->has('exercise')) {
             // Main meeting
             $main = $meeting;
             
             // Find all related exercises:
             // 1. The main meeting itself (Exercise 1)
             // 2. Any sub-meetings (>50) that start with the main meeting's title
             $exercises = \App\Models\ToeflStructureMeeting::where('meeting_number', $number)
                ->orWhere(function($q) use ($main) {
                    $q->where('meeting_number', '>', 50)
                      ->where('title', 'like', $main->title . '%');
                })
                ->orderBy('meeting_number')
                ->get();

             return view('assignments.toefl-itp.structure.selection', compact('exercises', 'main'));
        }

        // If we relate here, it means either:
        // 1. We are accessing a Main Meeting with ?exercise=1 (so we show the questions)
        // 2. We are accessing a Sub Meeting (e.g. 62) directly (so we show the questions)

        $title = $meeting->title;
        $questions = \App\Models\ToeflStructureQuestion::where('section_id', $meeting->id)->orderBy('question_number')->get();

        return view('assignments.toefl-itp.structure.meeting', compact('number', 'title', 'questions'));
    }

    public function addStructureSet(\Illuminate\Http\Request $request, $number)
    {
        // $number is the Main Meeting Number
        $parent = \App\Models\ToeflStructureMeeting::where('meeting_number', $number)->firstOrFail();

        // 1. Find next available number > 50 (Global sequence to avoid collision)
        // Assuming we just increment from the max existing > 50
        $max = \App\Models\ToeflStructureMeeting::where('meeting_number', '>', 50)
            ->max('meeting_number');
            
        $next = $max ? $max + 1 : 51; // Start at 51 if none exist

        // 2. Calculate the "Exercise Index" for the title
        // Count how many exercises this parent already has
        $currentCount = \App\Models\ToeflStructureMeeting::where('title', 'like', $parent->title . '%')->count();
        $nextIndex = $currentCount + 1;

        \App\Models\ToeflStructureMeeting::create([
            'meeting_number' => $next,
            'title' => $parent->title . ' (Exercise ' . $nextIndex . ')',
            'is_locked' => 0
        ]);
        
        // Add placeholder question
        $newMeeting = \App\Models\ToeflStructureMeeting::where('meeting_number', $next)->first();
        \App\Models\ToeflStructureQuestion::create([
            'section_id' => $newMeeting->id,
            'question_number' => 1,
            'question_text' => 'New Exercise Placeholder',
            'option_a' => 'A',
            'option_b' => 'B',
            'option_c' => 'C',
            'option_d' => 'D',
            'correct_answer' => 'A'
        ]);

        return back()->with('success', 'New exercise added successfully.');
    }

    public function removeStructureSet(\Illuminate\Http\Request $request, $number)
    {
        // $number here is the Parent number (6) but we need to delete the specific child
        // Passed via input 'meeting_id' or 'target_number'
        $targetNumber = $request->input('target_number');
        
        if ($targetNumber == 6) {
            return back()->with('error', 'Cannot delete the main lesson here.');
        }

        $meeting = \App\Models\ToeflStructureMeeting::where('meeting_number', $targetNumber)->first();
        if ($meeting) {
            $meeting->delete();
            return back()->with('success', 'Exercise deleted successfully.');
        }

        return back()->with('error', 'Meeting not found.');
    }

