    public function submitStructureMeeting(Request $request, $number)
    {
        $meeting = \App\Models\ToeflStructureMeeting::where('meeting_number', $number)->firstOrFail();
        $questions = \App\Models\ToeflStructureQuestion::where('section_id', $meeting->id)->get();

        $correctCount = 0;
        $userAnswers = $request->input('answers', []);
        
        foreach ($questions as $question) {
            $userAnswer = $userAnswers[$question->id] ?? null;
            if ($userAnswer === $question->correct_answer) {
                $correctCount++;
            }
        }

        $score = $questions->count() > 0 ? ($correctCount / $questions->count()) * 100 : 0;

        // Custom Scoring for Meeting 16 (TOEFL ITP Structure Section 2)
        if ($number == 16 && $questions->count() == 40) {
            $conversion = [
                40 => 68, 39 => 68, 38 => 68, 
                37 => 65, 36 => 63,
                35 => 61, 34 => 60, 33 => 59,
                32 => 58, 31 => 57, 30 => 56,
                29 => 55, 28 => 54, 27 => 53,
                26 => 52, 25 => 51, 24 => 50,
                23 => 49, 22 => 48, 21 => 48,
                20 => 47, 19 => 46, 18 => 45,
                17 => 44, 16 => 43, 15 => 42,
                14 => 40, 13 => 39, 12 => 38,
                11 => 36, 10 => 34, 9 => 32,
                8 => 31, 7 => 31, 6 => 31,
                5 => 31, 4 => 31, 3 => 31, 2 => 31, 1 => 31, 0 => 31
            ];
            $score = ($conversion[$correctCount] ?? 31) * 10;
        }

        return back()->with('score_data', [
            'score' => $score,
            'correct_count' => $correctCount,
            'total_questions' => $questions->count(),
            'user_answers' => $userAnswers
        ])->with('success', "Score: {$score}% ({$correctCount}/{$questions->count()} correct)");
    }

