    public function listeningMeeting($number)
    {
        $user = Auth::user();
        
        // Validate meeting number
        if (($number < 1 || $number > 20) && !in_array($number, [101, 102, 103])) {
            abort(404);
        }
        
        // Check lock status
        $meeting = \App\Models\ToeflListeningMeeting::where('meeting_number', $number)->first();
        $batchLockMap = collect();
        $selectedClassPeriod = $this->resolveToeflSelectedClassPeriod($user);
        if ($selectedClassPeriod) {
            $batchLockMap = \App\Models\ClassPeriodToeflMeeting::where('class_period_id', $selectedClassPeriod->id)
                ->where('module', 'listening')
                ->pluck('is_open', 'meeting_number');
        }
        $isLocked = $meeting ? $this->resolveToeflLockedState($batchLockMap, (int) $meeting->meeting_number, (bool) $meeting->is_locked, (bool) $selectedClassPeriod) : false;
        if ($isLocked) {
            return redirect()->route('assignments.toefl-itp.listening')
                ->with('error', 'This meeting is currently locked.');
        }

        $transcript_enabled = $meeting ? $meeting->transcript_enabled : false;
        
        // Get questions for this meeting
        $questions = \App\Models\ToeflListeningQuestion::byMeeting($number)->get();
        
        // Check if already submitted
        $existingScore = \App\Models\ToeflListeningScore::where('user_id', $user->id)
            ->where('meeting_number', $number)
            ->first();
        
        // Calculate available sets
        $availableSets = \App\Models\ToeflListeningQuestion::where('meeting_number', $number)
            ->distinct()
            ->pluck('set_number')
            ->sort()
            ->values()
            ->toArray();

        // Fallback for Meetings 2, 3, 4 if no sets found (shouldn't happen if seeded)
        if (empty($availableSets) && in_array($number, [2, 3, 4])) {
            $availableSets = [1, 2, 3];
        }
        
        // Map meeting numbers to their respective views
        if ($number >= 2 && $number <= 16) {
            $viewName = 'assignments.toefl-itp.listening.meeting' . ($number > 1 ? $number : '');
            return view($viewName, compact('questions', 'number', 'existingScore', 'availableSets', 'transcript_enabled'));
        }
    
        return view('assignments.toefl-itp.listening.meeting', compact('questions', 'number', 'existingScore', 'availableSets', 'transcript_enabled'));
    }

