    public function removePracticeSet(Request $request, $number)
    {
        $targetSet = $request->input('set_number');

        if ($targetSet) {
             // Delete specific set
             \App\Models\ToeflListeningQuestion::where('meeting_number', $number)
                ->where('set_number', $targetSet)
                ->delete();
                
             \App\Models\ToeflListeningScore::where('meeting_number', $number)
                ->where('set_number', $targetSet)
                ->delete();

             return back()->with('success', 'Practice Set ' . $targetSet . ' removed successfully.');
        }

        // Fallback: Find max set number
        $maxSet = \App\Models\ToeflListeningQuestion::where('meeting_number', $number)
            ->max('set_number');

        if (!$maxSet || $maxSet <= 1) {
            return back()->with('error', 'Cannot remove the last practice set.');
        }

        // Delete all questions in this set
        \App\Models\ToeflListeningQuestion::where('meeting_number', $number)
            ->where('set_number', $maxSet)
            ->delete();
            
        \App\Models\ToeflListeningScore::where('meeting_number', $number)
            ->where('set_number', $maxSet)
            ->delete();
            
        // Also delete scores? Maybe keep for history? 
        // For cleanup, let's delete associated scores too.
        \App\Models\ToeflListeningScore::where('meeting_number', $number)
            ->where('set_number', $maxSet)
            ->delete();

        return back()->with('success', 'Practice Set ' . $maxSet . ' removed successfully.');
    }
    
    public function uploadListeningAudio(Request $request, $number, $set)
    {
        $user = Auth::user();
        
        // Check if user is admin
        if (!$user->isAdmin()) {
            return redirect()->back()->with('error', 'Unauthorized access.');
        }

        // Validate the request
    $request->validate([
        'audio_file' => 'required|file|mimes:mp3,wav,ogg|max:51200', // 50MB max
    ]);
        
        // Handle file upload
    if ($request->hasFile('audio_file')) {
        try {
            $file = $request->file('audio_file');
            
            if (!$file->isValid()) {
                 return redirect()->back()->with('error', 'File is not valid. Error code: ' . $file->getError());
            }

            // cleanup old file logic
            $existingQuestion = \App\Models\ToeflListeningQuestion::where('meeting_number', $number)
                ->where('set_number', $set)
                ->first();

            if ($existingQuestion && $existingQuestion->audio_file) {
                 $oldPath = public_path($existingQuestion->audio_file);
                 if (file_exists($oldPath)) {
                     @unlink($oldPath);
                 }
            }

            // Create directory path
            $directory = "audio/toefl-listening/meeting-{$number}/set-{$set}";
            $publicPath = public_path($directory);
            
            // Create directory if it doesn't exist
            if (!file_exists($publicPath)) {
                if (!mkdir($publicPath, 0777, true)) {
                    return redirect()->back()->with('error', 'Failed to create directory: ' . $publicPath);
                }
            }
            
            // Generate filename
            $filename = 'audio_' . time() . '.' . $file->getClientOriginalExtension();
            
            // Move file to public directory
            $file->move($publicPath, $filename);
            
            // Update all questions in this set with the audio file path
            $audioPath = $directory . '/' . $filename;
            
            // Verify file exists after move
            if (!file_exists($publicPath . '/' . $filename)) {
                 return redirect()->back()->with('error', 'File move failed. Check permissions.');
            }

            \App\Models\ToeflListeningQuestion::where('meeting_number', $number)
                ->where('set_number', $set)
                ->update(['audio_file' => $audioPath]);
            
            // Auto-transcribe audio file
            try {
                $fullAudioPath = public_path($audioPath);
                $srtPath = $publicPath . '/transcript.srt';
                
                // Use Whisper to transcribe
                $process = new \Symfony\Component\Process\Process([
                    'whisper',
                    $fullAudioPath,
                    '--model', 'base',
                    '--language', 'en',
                    '--output_format', 'srt',
                    '--output_dir', $publicPath,
                    '--fp16', 'false',
                ]);
                
                $process->setTimeout(600); // 10 minutes
                $process->run();
                
                if ($process->isSuccessful() && file_exists($srtPath)) {
                    \App\Models\ToeflListeningQuestion::where('meeting_number', $number)
                        ->where('set_number', $set)
                        ->update(['transcript' => file_get_contents($srtPath)]);
                    
                    return redirect()->back()->with('success', 'Audio file uploaded and transcribed successfully!');
                } else {
                    return redirect()->back()->with('success', 'Audio file uploaded successfully! Transcription failed, but audio is ready.');
                }
            } catch (\Exception $e) {
                return redirect()->back()->with('success', 'Audio file uploaded successfully! Transcription error: ' . $e->getMessage());
            }
        } catch (\Exception $e) {
            return redirect()->back()->with('error', 'Exception during upload: ' . $e->getMessage());
        }
    }
    
    return redirect()->back()->with('error', 'No file received by server.');
}

    public function toggleListeningLock($number)
    {
        if (!Auth::check() || !(Auth::user()->isAdmin() || Auth::user()->isTeacher())) {
            abort(403);
        }

        $meeting = \App\Models\ToeflListeningMeeting::where('meeting_number', $number)->firstOrFail();
        $classPeriodId = request()->integer('class_period_id');
        if ($classPeriodId) {
            $batchRule = \App\Models\ClassPeriodToeflMeeting::where('class_period_id', $classPeriodId)
                ->where('module', 'listening')
                ->where('meeting_number', $meeting->meeting_number)
                ->first();

            if ($batchRule) {
                $batchRule->update(['is_open' => !$batchRule->is_open]);
                $isOpenNow = (bool) $batchRule->fresh()->is_open;
            } else {
                \App\Models\ClassPeriodToeflMeeting::create([
                    'class_period_id' => $classPeriodId,
                    'module' => 'listening',
                    'meeting_number' => $meeting->meeting_number,
                    'is_open' => true,
                ]);
                $isOpenNow = true;
            }

            $classPeriod = \App\Models\ClassPeriod::find($classPeriodId);
            $label = $isOpenNow ? 'OPEN' : 'LOCKED';
            return back()->with('success', "Meeting is now {$label} for batch {$classPeriod->name}.");
        }

        $meeting->is_locked = !$meeting->is_locked;
        $meeting->save();
        
        return back()->with('success', 'Meeting lock status updated.');
    }

    public function toggleTranscriptLock($number)
    {
        if (!Auth::check() || !(Auth::user()->isAdmin() || Auth::user()->isTeacher())) {
