    public function uploadSrt(Request $request, $number, $set)
    {
        // Admin validation
        if (!Auth::user()->isAdmin()) {
            abort(403);
        }

        $request->validate([
            'srt_file' => 'required_without:srt_content|nullable|file|extensions:srt|max:2048', // 2MB max
            'srt_content' => 'required_without:srt_file|nullable|string',
            'language' => 'required|in:en,id',
        ]);

        $content = '';
        if ($request->hasFile('srt_file')) {
            $file = $request->file('srt_file');
            $content = file_get_contents($file->getRealPath());
        } elseif ($request->filled('srt_content')) {
            $content = $request->input('srt_content');
        }

        if (!empty($content)) {
            // Normalize line endings
            $content = str_replace("\r\n", "\n", $content);

            // Parsing Logic: Convert SRT to JSON with timestamps
            // Regex to match SRT blocks:
            // Group 1: Sequence number
            // Group 2: Start time (supports HH:MM:SS,ms or H:i:s.ms)
            // Group 3: End time
            // Group 4: Text content
            // Regex to match SRT blocks:
            // Flexible pattern:
            // 1. Index (digits)
            // 2. Separator (newline OR space)
            // 3. Start Time 
            // 4. Arrow 
            // 5. End Time
            // 6. Text (until next index+timestamp pattern or end of string)
            $pattern = '/(\d+)\s+(\d{1,2}:\d{2}:\d{2}[,.]\d{1,3})\s*-->\s*(\d{1,2}:\d{2}:\d{2}[,.]\d{1,3})\s+([\s\S]*?)(?=(?:\n\s*\d+\s+\d{1,2}:\d{2}:\d{2})|$)/';
            
            $blocks = [];
            if (preg_match_all($pattern, $content, $matches, PREG_SET_ORDER)) {
                foreach ($matches as $match) {
                    $startTime = $this->srtTimeToSeconds($match[2]);
                    $endTime = $this->srtTimeToSeconds($match[3]);
                    $text = trim($match[4]);
                    $text = str_replace("\n", " ", $text); // Optional: flatten newlines within a block
                    
                    if (!empty($text)) {
                        $blocks[] = [
                            'start' => $startTime,
                            'end' => $endTime,
                            'text' => $text
                        ];
                    }
                }
            }

            // Fallback: if regex fails (empty blocks), might be plain text or weird format
            if (empty($blocks)) {
                // If parsing failed entirely, just save as plain text (legacy behavior)
                 // But we want to encourage JSON, so let's try a simpler split if regex failed
                 // For now, let's assume valid SRT. If empty, save as empty JSON or raw content.
                 // Let's stick to storing JSON if possible.
                 $finalText = json_encode([]);
                 if (empty($matches)) {
                     // If really no matches, maybe it's not a valid SRT. 
                     // Let's just store the content cleaned up as a single block 0-end? 
                     // Or just legacy text.
                     // Decision: If regex fails, store as plain text string (legacy).
                     // Frontend will check if it's JSON or not.
                     $finalText = $content; 
                 } else {
                     $finalText = json_encode($blocks);
                 }
            } else {
                $finalText = json_encode($blocks);
            }

            // Determine column to update
            $column = ($request->language === 'en') ? 'transcript_en' : 'transcript_id';

            // Update database
            \App\Models\ToeflListeningQuestion::where('meeting_number', $number)
                ->where('set_number', $set)
                ->update([$column => $finalText]);

            return back()->with('success', 'SRT uploaded and parsed successfully.');
        }

        return back()->with('error', 'Failed to upload SRT file.');
    }

    public function listeningMeetingSubmit(Request $request, $number)
    {
        $user = Auth::user();
        
        // Validate meeting number
    if (($number < 1 || $number > 20) && $number != 101 && $number != 102) {
        abort(404);
    }
        
        $setNumber = $request->input('set_number');

        // Get questions for this meeting
        $query = \App\Models\ToeflListeningQuestion::byMeeting($number);
        
        if ($setNumber) {
            $query->where('set_number', $setNumber);
        }

        $questions = $query->get();
        
        // Calculate score
        $correctCount = 0;
        $userAnswers = [];
        
        foreach ($questions as $question) {
            $userAnswer = $request->input("question_{$question->id}");
            $userAnswers[$question->id] = $userAnswer;
            
            if ($userAnswer === $question->correct_answer) {
                $correctCount++;
            }
        }
        
        // Calculate percentage score
        $score = $questions->count() > 0 ? ($correctCount / $questions->count()) * 100 : 0;
        
        // Prepare update criteria
        $updateCriteria = [
            'user_id' => $user->id,
            'meeting_number' => $number,
        ];

        if ($setNumber) {
            $updateCriteria['set_number'] = $setNumber;
        }

        // Save or update score
        \App\Models\ToeflListeningScore::updateOrCreate(
            $updateCriteria,
            [
                'score' => $score,
                'answers' => $userAnswers,
                'submitted_at' => now(),
            ]
        );
        
        if ($setNumber) {
             return redirect()->route('assignments.toefl-itp.listening.meeting.practice', ['number' => $number, 'set' => $setNumber])
            ->with('success', "Score (Set $setNumber): {$score}% ({$correctCount}/{$questions->count()} correct)")
            ->with('score_data', [
                'score' => $score,
                'correct_count' => $correctCount,
                'total_question' => $questions->count(),
                'user_answers' => $userAnswers
            ]);
        }

        return redirect()->route('assignments.toefl-itp.listening.meeting', $number)
            ->with('success', "Score: {$score}% ({$correctCount}/{$questions->count()} correct)")
            ->with('score_data', [
                'score' => $score,
                'correct_count' => $correctCount,
                'total_question' => $questions->count(),
                'user_answers' => $userAnswers
            ]);
    }

    public function storeListeningQuestion(Request $request)
    {
        $request->validate([
            'id' => 'nullable|integer',
            'meeting_number' => 'required|integer|min:1|max:20',
            'question_number' => 'required|integer',
            'question_text' => 'required|string',
            'option_a' => 'required|string',
            'option_b' => 'required|string',
            'option_c' => 'required|string',
            'option_d' => 'required|string',
            'correct_answer' => 'required|in:A,B,C,D',
            'audio_file' => 'nullable|file|mimes:mp3,wav|max:5120', // Max 5MB
        ]);

        $data = $request->except(['id', 'audio_file']);

        // Handle Audio Upload
        if ($request->hasFile('audio_file')) {
            $file = $request->file('audio_file');
            $filename = 'audio_' . time() . '_' . $file->getClientOriginalName();
            $file->move(public_path('audio/listening'), $filename);
            $data['audio_file'] = 'audio/listening/' . $filename;
        }

        if ($request->id) {
            // Update existing question
            $question = \App\Models\ToeflListeningQuestion::findOrFail($request->id);
            
            // Delete old audio if new one is uploaded
            if ($request->hasFile('audio_file') && $question->audio_file && file_exists(public_path($question->audio_file))) {
                unlink(public_path($question->audio_file));
            }
            
            $question->update($data);
            $message = 'Question updated successfully.';
        } else {
            // Create new question
            \App\Models\ToeflListeningQuestion::create($data);
            $message = 'Question created successfully.';
        }

        return back()->with('success', $message);
    }

    public function deleteListeningQuestion($id)
    {
        $question = \App\Models\ToeflListeningQuestion::findOrFail($id);
        
        // Delete audio file
        if ($question->audio_file && file_exists(public_path($question->audio_file))) {
            unlink(public_path($question->audio_file));
        }
        
        $question->delete();
        
        return back()->with('success', 'Question deleted successfully.');
    }

