    {
        $user = Auth::user();
        if (!$user || (!$user->isAdmin() && !$user->isTeacher())) {
            abort(403);
        }

        $request->validate([
            'period' => 'required|string|max:255',
        ]);

        $program = \App\Models\Program::where('slug', 'grammar-for-writing')->firstOrFail();
        $program->update(['period' => $request->period]);

