    private function getDiffFeedback($userWords, $correctWords) {
        $matrix = [];
        $n = count($userWords);
        $m = count($correctWords);
        
        for ($i = 0; $i <= $n; $i++) $matrix[$i][0] = 0;
        for ($j = 0; $j <= $m; $j++) $matrix[0][$j] = 0;
        
        for ($i = 1; $i <= $n; $i++) {
            for ($j = 1; $j <= $m; $j++) {
                $uWord = strtolower(rtrim($userWords[$i-1], '.!,'));
                $cWord = strtolower(rtrim($correctWords[$j-1], '.!,'));
                
                if ($uWord === $cWord) {
                    $matrix[$i][$j] = $matrix[$i-1][$j-1] + 1;
                } else {
                    $matrix[$i][$j] = max($matrix[$i-1][$j], $matrix[$i][$j-1]);
                }
            }
        }
        
        $i = $n;
        $j = $m;
        $diff = [];
        
        while ($i > 0 || $j > 0) {
            if ($i > 0 && $j > 0) {
                $uWord = strtolower(rtrim($userWords[$i-1], '.!,'));
                $cWord = strtolower(rtrim($correctWords[$j-1], '.!,'));
                
                if ($uWord === $cWord) {
                    array_unshift($diff, ['type' => 'match', 'word' => $userWords[$i-1]]);
                    $i--; $j--;
                    continue;
                }
            }
            
            if ($j > 0 && ($i == 0 || $matrix[$i][$j-1] >= $matrix[$i-1][$j])) {
                array_unshift($diff, ['type' => 'missing', 'word' => $correctWords[$j-1]]);
                $j--;
            } else if ($i > 0 && ($j == 0 || $matrix[$i][$j-1] < $matrix[$i-1][$j])) {
                array_unshift($diff, ['type' => 'extra', 'word' => $userWords[$i-1]]);
                $i--;
            }
        }
        
        $finalOutput = [];
        $count = count($diff);
        for ($k = 0; $k < $count; $k++) {
            $current = $diff[$k];
            $next = ($k + 1 < $count) ? $diff[$k+1] : null;
            
            if ($current['type'] == 'extra' && $next && $next['type'] == 'missing') {
                $finalOutput[] = '<span class="word-wrong">' . htmlspecialchars($current['word']) . '</span>';
                $finalOutput[] = '<span class="word-missing">(' . htmlspecialchars($next['word']) . ')</span>';
                $k++;
            } elseif ($current['type'] == 'match') {
                $finalOutput[] = '<span class="word-correct">' . htmlspecialchars($current['word']) . '</span>';
            } elseif ($current['type'] == 'extra') {
                $finalOutput[] = '<span class="word-extra">' . htmlspecialchars($current['word']) . '</span>';
            } elseif ($current['type'] == 'missing') {
                $finalOutput[] = '<span class="word-missing">(' . htmlspecialchars($current['word']) . ')</span>';
            }
        }
        
        return implode(' ', $finalOutput);
    }

