    public function meeting2(Request $request)
    {
        $stage = session('meeting2_stage', 1);
        $results = session('meeting2_results', []);
        $transResults = session('meeting2_trans_results', []);
        $scorePart1 = session('meeting2_score_part1', 0);
        $scorePart2 = session('meeting2_score_part2', 0);
        $totalScore = session('meeting2_total_score', 0);

        // Fetch data from DB
        $sentences = \App\Models\GrammarQuestion::where('meeting_number', 2)
            ->where('section', 'sentences')
            ->orderBy('question_number')
            ->get()
            ->map(function($q) {
                return [
                    'id' => $q->question_text,
                    'en' => $q->correct_answer,
                    'tense' => $q->tense,
                    'type' => $q->structure,
                    'question_number' => $q->question_number,
                    'original_id' => $q->id
                ];
            });

        // Fetch Matrix
        $rawMatrix = \App\Models\GrammarQuestion::where('meeting_number', 2)
            ->where('section', 'matrix')
            ->orderBy('question_number')
            ->get();
        
        $translationMatrix = [];
        $tenses = [];
        $tenseExamples = [];

        foreach ($rawMatrix as $q) {
            $translationMatrix[$q->tense][$q->structure] = [
                'id' => $q->question_text,
                'en' => $q->correct_answer,
                'question_number' => $q->question_number,
                'original_id' => $q->id
            ];
            
            // Reconstruct tenses formula/structure list (if needed by view)
            // For now, simple reconstruction from loop
            $tenses[$q->tense][$q->structure] = $q->formula ?? ''; // If formula col added
            
            // Examples
            if ($q->example_id) {
                $tenseExamples[$q->tense][$q->structure] = [
                    'id' => $q->example_id,
                    'en' => $q->example_en
                ];
            }
        }

        // Tenses and Formulas might still need to be hardcoded if not in DB fully,
        // or fetched from a separate table if normalization was strict. 
        // But Meeting 2 view uses $tenses mainly for formulas.
        // Since I only migrated Sentences/Matrix questions, the FORMULAS might be missing if I didn't store them.
        // Wait, I mapped `formula` => null in seeder :(
        // The View uses $tenses to show formulas!
        // I should probably keep $this->meeting2Tenses for formulas OR update Seeder to include formulas.
        // For now, to allow CRUD of QUESTIONS, I will merge/fallback.
        // Actually, let's use the hardcoded $this->meeting2Tenses for formulas as a fallback if DB is empty/null,
        // BUT the view loops over $this->meeting2Tenses to build the matrix table structure.
        
        // Better approach: Use the DB to drive the structure IF the DB has all rows.
        // The Seeder populated all rows.
        // But `formula` is null in DB.
        // I will stick to hardcoded formulas for now to avoid breaking the view display of formulas,
        // BUT assume text/answers come from DB.
        
        // HOWEVER, the view iterates `foreach($tenses as $tenseName => $items)`
        // If I pass $tenses from DB (which has null formulas), formulas will be empty.
        // I should use the hardcoded property for the STRUCTURE and FORMULAS, but inject DB values for questions.
        
        // Let's keep $this->meeting2Tenses for now as the "Skeleton",
        // and override the question values with DB values.

        return view('assignments.grammar-writing.meeting2', [
            'tenses' => $this->meeting2Tenses, 
            'translationSentences' => $sentences, // Use Collection mapped to array
            'translationMatrix' => $translationMatrix, // Dynamic
            'tenseExamples' => $this->meeting2TenseExamples, // Keep hardcoded examples for now or fetch if stored
            'vocabularies' => $this->meeting2Vocabularies,
            'stage' => $stage,
            'results' => $results,
            'transResults' => $transResults,
            'scorePart1' => $scorePart1,
            'scorePart2' => $scorePart2,
            'totalScore' => $totalScore
        ]);
    }

    public function meeting2Submit(Request $request)
    {
        $stage = session('meeting2_stage', 1);

        if ($stage === 1) {
            $results = [];
            $scorePart1 = 0;
            $totalItems = 0;

            foreach ($this->meeting2Tenses as $tenseName => $formulas) {
                foreach (['verbal', 'nominal', 'passive'] as $type) {
                    $key = str_replace(' ', '_', strtolower($tenseName)) . '_' . $type;
                    $userAnswer = trim($request->input('tenses.' . $key, ''));
                    $correctAnswer = $formulas[$type];
                    
                    // Normalize for comparison (remove spaces, lowercase)
                    $normUser = strtolower(preg_replace('/\s+/', '', $userAnswer));
                    $normCorrect = strtolower(preg_replace('/\s+/', '', $correctAnswer));

                    $isCorrect = $normUser === $normCorrect;
                    if ($isCorrect) $scorePart1++;
                    $totalItems++;

                    $results[$tenseName][$type] = [
                        'user_answer' => $userAnswer,
                        'correct_answer' => $correctAnswer,
                        'is_correct' => $isCorrect
                    ];
                }
            }

            // Calculate Part 1 Score (Max 50)
            $finalScorePart1 = ($totalItems > 0) ? round(($scorePart1 / $totalItems) * 50) : 0;
            
            session([
                'meeting2_stage' => 2,
                'meeting2_results' => $results,
                'meeting2_score_part1' => $finalScorePart1
            ]);

            return redirect()->route('assignments.grammar-writing.meeting2');

        } elseif ($stage === 2) {
            $transResults = ['sentences' => [], 'matrix' => []];
            $scorePart2 = 0;
            $totalItems = 0;

            // Check Sentences
            foreach ($this->meeting2TranslationSentences as $idx => $item) {
                $userAnswer = trim($request->input('trans_sent.' . $idx, ''));
                $correctAnswer = $item['en'];
                
                $isCorrect = strtolower(rtrim($userAnswer, '.!')) === strtolower(rtrim($correctAnswer, '.!'));
                if ($isCorrect) $scorePart2++;
                $totalItems++;

                $transResults['sentences'][$idx] = [
                    'user_answer' => $userAnswer,
                    'correct_answer' => $correctAnswer,
                    'is_correct' => $isCorrect
                ];
            }

            // Check Matrix
            foreach ($this->meeting2TranslationMatrix as $tenseName => $items) {
                foreach (['verbal', 'nominal', 'passive'] as $type) {
                    $key = str_replace(' ', '_', strtolower($tenseName)) . '_' . $type;
                    $userAnswer = trim($request->input('trans_matrix.' . $key, ''));
                    $correctAnswer = $items[$type]['en'];

                    $isCorrect = strtolower(rtrim($userAnswer, '.!')) === strtolower(rtrim($correctAnswer, '.!'));
                    if ($isCorrect) $scorePart2++;
                    $totalItems++;

                    $transResults['matrix'][$tenseName][$type] = [
                        'user_answer' => $userAnswer,
                        'correct_answer' => $correctAnswer,
                        'is_correct' => $isCorrect
                    ];
                }
            }

            // Calculate Part 2 Score (Max 50)
            $finalScorePart2 = ($totalItems > 0) ? round(($scorePart2 / $totalItems) * 50) : 0;
            $scorePart1 = session('meeting2_score_part1', 0);
            $totalScore = $scorePart1 + $finalScorePart2;

            session([
                'meeting2_stage' => 3,
                'meeting2_trans_results' => $transResults,
                'meeting2_score_part2' => $finalScorePart2,
                'meeting2_total_score' => $totalScore
            ]);

            // Save score to database
            $this->saveMeetingScore(2, $totalScore);

            return redirect()->route('assignments.grammar-writing.meeting2');
        }

        return redirect()->route('assignments.grammar-writing.meeting2');
    }

    public function meeting2Reset()
    {
        session()->forget([
            'meeting2_stage', 
            'meeting2_results', 
            'meeting2_trans_results', 
            'meeting2_score_part1', 
            'meeting2_score_part2', 
            'meeting2_total_score'
        ]);
        return redirect()->route('assignments.grammar-writing.meeting2');
    }

    private function grammarQuestionsHasSectionColumn(): bool
    {
        static $hasSectionColumn = null;

        if ($hasSectionColumn === null) {
            $hasSectionColumn = \Illuminate\Support\Facades\Schema::hasColumn('grammar_questions', 'section');
        }

        return $hasSectionColumn;
    }

