    public function meeting3(Request $request)
    {
        $submitted = session('meeting3_submitted', false);
        $results = session('meeting3_results', []);
        $paragraphResult = session('meeting3_paragraph_result', []);
        $finalScore = session('meeting3_final_score', 0);
        $userAnswers = session('meeting3_user_answers', []);
        $userParagraphAnswer = session('meeting3_user_paragraph_answer', '');

        $hasSectionColumn = $this->grammarQuestionsHasSectionColumn();

        // Fetch Questions
        $questionsQuery = \App\Models\GrammarQuestion::where('meeting_number', 3)
            ->orderBy('question_number');

        if ($hasSectionColumn) {
            $questionsQuery->where('section', 'sentences');
        }

        $questions = $questionsQuery->get()
            ->filter(function ($q) use ($hasSectionColumn) {
                // Legacy schema stores only sentence rows unless a dedicated paragraph marker (q_num 999) exists.
                return $hasSectionColumn || (int) $q->question_number !== 999;
            })
            ->map(function ($q) {
                return [
                    'id' => $q->question_text,
                    'en' => $q->correct_answer,
                    'tense' => $q->tense,
                    'vocab' => $q->vocab,
                    'original_id' => $q->id,
                    'q_num' => $q->question_number,
                ];
            });

        if ($questions->isEmpty()) {
            $questions = collect($this->meeting3FallbackQuestions)->map(function ($q, $number) {
                return [
                    'id' => $q['id'],
                    'en' => $q['en'],
                    'tense' => $q['tense'],
                    'vocab' => $q['vocab'] ?? [],
                    'original_id' => 0,
                    'q_num' => (int) $number,
                ];
            });
        }

        // Fetch Paragraph
        $paragraphQuery = \App\Models\GrammarQuestion::where('meeting_number', 3);
        if ($hasSectionColumn) {
            $paragraphQuery->where('section', 'paragraph');
        } else {
            $paragraphQuery->where('question_number', 999);
        }
        $paragraph = $paragraphQuery->first();

        $paragraphData = $paragraph
            ? [
                'id' => $paragraph->question_text,
                'en' => $paragraph->correct_answer,
                'vocab' => $paragraph->vocab
            ]
            : [
                'id' => $this->meeting3FallbackParagraph['id'],
                'en' => $this->meeting3FallbackParagraph['en'],
                'vocab' => $this->meeting3FallbackParagraph['vocab']
            ];

        return view('assignments.grammar-writing.meeting3', [
            'questions' => $questions,
            'fullParagraphId' => $paragraphData['id'],
            'fullParagraphEn' => $paragraphData['en'],
            'paragraphVocab' => $paragraphData['vocab'], // Pass simplified vocab
            'submitted' => $submitted,
            'results' => $results,
            'paragraphResult' => $paragraphResult,
            'finalScore' => $finalScore,
            'userAnswers' => $userAnswers,
            'userParagraphAnswer' => $userParagraphAnswer,
            'paragraphId' => $paragraph->id ?? 0 // For Admin Edit
        ]);
    }

    public function meeting3Submit(Request $request)
    {
        $userAnswers = $request->input('userAnswers', []);
        $userParagraphAnswer = $request->input('userParagraphAnswer', '');
        
        $hasSectionColumn = $this->grammarQuestionsHasSectionColumn();

        // Fetch Questions
        $questionsQuery = \App\Models\GrammarQuestion::where('meeting_number', 3)
            ->orderBy('question_number');

        if ($hasSectionColumn) {
            $questionsQuery->where('section', 'sentences');
        }

        $questions = $questionsQuery->get()->filter(function ($q) use ($hasSectionColumn) {
            return $hasSectionColumn || (int) $q->question_number !== 999;
        })->values();

        if ($questions->isEmpty()) {
            $questions = collect($this->meeting3FallbackQuestions)->map(function ($q, $number) {
                return (object) [
                    'question_number' => (int) $number,
                    'correct_answer' => $q['en'],
                    'tense' => $q['tense'],
                ];
            })->values();
        }
            
        // Fetch Paragraph
        $paragraphQuery = \App\Models\GrammarQuestion::where('meeting_number', 3);
        if ($hasSectionColumn) {
            $paragraphQuery->where('section', 'paragraph');
        } else {
            $paragraphQuery->where('question_number', 999);
        }
        $paragraphData = $paragraphQuery->first();

        if (!$paragraphData) {
            $paragraphData = (object) [
                'correct_answer' => $this->meeting3FallbackParagraph['en'],
            ];
        }

        $results = [];
        $totalScore = 0;
        $maxScore = ($questions->count() * 10) + 20; // 5 for tense, 5 for trans per question + 20 for paragraph

        // Check Questions
        foreach ($questions as $idx => $q) {
            // Adjust index to match 1-based view index if needed, or use loop index
            // The view uses $idx from foreach which is 1-based in original array but 0-based in collection
            // Let's rely on data matching by order. 
            // NOTE: Original code used 1-based index for $userAnswers keys.
            // Validating: The view loop is specific.
            // To be safe, we'll map question_number from DB to user answer key.
            
            $qNum = $q->question_number;
            $uTense = trim($userAnswers[$qNum]['tense'] ?? '');
            $uTrans = trim($userAnswers[$qNum]['trans'] ?? '');
            
            // Score Tense (Exact match, case insensitive)
            $tenseScore = 0;
            if (strtolower($uTense) === strtolower($q->tense)) {
                $tenseScore = 5;
            }

            // SCORE TRANSLATION (Best Match Scheme)
            $variants = explode('|', $q->correct_answer);
            $bestScore = -1;
            $bestDiff = null;
            $bestMatchCount = 0;
            // $bestVariant = $variants[0]; // Not explicitly needed if we capture bestDiff

            foreach ($variants as $variant) {
                $variant = trim($variant);
                
                $correctWords = preg_split('/\s+/', $variant, -1, PREG_SPLIT_NO_EMPTY);
                $userWords = preg_split('/\s+/', $uTrans, -1, PREG_SPLIT_NO_EMPTY);
                
                $matchCount = 0;
                foreach ($userWords as $uw) {
                    foreach ($correctWords as $cw) {
                        if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                            $matchCount++;
                            break; 
                        }
                    }
                }

                // Simple ratio score for this variant
                $currentTransScore = 0;
                if (count($correctWords) > 0) {
                     $ratio = $matchCount / count($correctWords);
                     if ($ratio == 1) $currentTransScore = 5;
                     elseif ($ratio >= 0.8) $currentTransScore = 4;
                     elseif ($ratio >= 0.6) $currentTransScore = 3;
                     elseif ($ratio >= 0.4) $currentTransScore = 2;
                     elseif ($ratio > 0) $currentTransScore = 1;
                }
                
                // Track best score
                if ($currentTransScore > $bestScore) {
                    $bestScore = $currentTransScore;
                    $bestMatchCount = $matchCount;
                    
                    // Generate Diff for this variant
                    $bestDiff = new \Diff(
                        explode(' ', $variant),
                        explode(' ', $uTrans),
                        ['ignoreWhitespace' => true, 'ignoreCase' => true]
                    );
                }
            }
            
            // If internal logic somehow fails to set bestDiff (e.g. empty variants), fallback
            if (!$bestDiff) {
                 $bestDiff = new \Diff(
                    explode(' ', $variants[0]),
                    explode(' ', $uTrans),
                    ['ignoreWhitespace' => true, 'ignoreCase' => true]
                );
                $bestScore = 0;
            }

            $transScore = max(0, $bestScore); // Ensure non-negative
            
            $totalScore += ($tenseScore + $transScore);

            $results[$qNum] = [ // Use qNum as key
                'tense_score' => $tenseScore,
                'trans_score' => $transScore,
                'user_tense' => $uTense,
                'user_trans' => $uTrans,
                'formatted_answer' => $bestDiff->render(new \Diff_Renderer_Html_Inline())
            ];
        }
        // Check Paragraph
        $paraCorrectWords = preg_split('/\s+/', $paragraphData->correct_answer ?? '', -1, PREG_SPLIT_NO_EMPTY);
        $paraUserWords = preg_split('/\s+/', $userParagraphAnswer, -1, PREG_SPLIT_NO_EMPTY);
        
        $paraMatchCount = 0;
        foreach ($paraUserWords as $uw) {
            foreach ($paraCorrectWords as $cw) {
                if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                    $paraMatchCount++;
                    break;
                }
            }
        }
        
        $paraScore = 0;
        if (count($paraCorrectWords) > 0) {
            $ratio = $paraMatchCount / count($paraCorrectWords);
            $paraScore = round($ratio * 20);
        }
        
        $paraFormatted = $this->getDiffFeedback($paraUserWords, $paraCorrectWords);
        $totalScore += $paraScore;
        
        // Normalize to 100
        $finalScore = round(($totalScore / $maxScore) * 100);

        session([
            'meeting3_submitted' => true,
            'meeting3_results' => $results,
            'meeting3_paragraph_result' => [
                'score' => $paraScore,
                'max_score' => 20,
                'formatted_answer' => $paraFormatted
            ],
            'meeting3_final_score' => $finalScore,
            'meeting3_user_answers' => $userAnswers,
            'meeting3_user_paragraph_answer' => $userParagraphAnswer
        ]);

        // Save score to database
        $this->saveMeetingScore(3, $finalScore);

        return redirect()->route('assignments.grammar-writing.meeting3');
    }

    public function meeting3Reset()
    {
        session()->forget([
            'meeting3_submitted', 
            'meeting3_results', 
            'meeting3_paragraph_result', 
            'meeting3_final_score', 
            'meeting3_user_answers', 
            'meeting3_user_paragraph_answer'
        ]);
        return redirect()->route('assignments.grammar-writing.meeting3');
    }

