    public function migrateMeeting5Data()
    {
        // 1. Migrate Simple Sentences
        if (\App\Models\GrammarQuestion::where('meeting_number', 5)->where('section', 'sentences')->count() == 0) {
            foreach ($this->meeting5Questions as $idx => $data) {
                \App\Models\GrammarQuestion::create([
                    'meeting_number' => 5,
                    'section' => 'sentences',
                    'question_number' => $idx,
                    'question_text' => $data['id'],
                    'correct_answer' => $data['en'],
                    'tense' => $data['tense']
                ]);
            }
        }

        // 2. Migrate Matrix
        if (\App\Models\GrammarQuestion::where('meeting_number', 5)->where('section', 'matrix')->count() == 0) {
            foreach ($this->meeting5Matrix as $tense => $types) {
                foreach ($types as $type => $data) {
                    if ($data) { // Only if data exists (not null)
                        \App\Models\GrammarQuestion::create([
                            'meeting_number' => 5,
                            'section' => 'matrix',
                            'question_number' => 0, // Not ordered by number
                            'tense' => $tense,
                            'structure' => $type,
                            'question_text' => $data['id'],
                            'correct_answer' => $data['en']
                        ]);
                    }
                }
            }
        }

        // 3. Migrate Vocabularies
        // Clear existing vocab for meeting 5 to prevent duplicates if re-run (or check check)
        // Better to check count
        if (\App\Models\GrammarVocabulary::where('meeting_number', 5)->count() == 0) {
            foreach ($this->meeting5Vocabularies as $tense => $types) {
                foreach ($types as $type => $vocabs) {
                    if ($vocabs) {
                        $sectionKey = $tense . ' - ' . $type;
                        foreach ($vocabs as $ind => $eng) {
                            \App\Models\GrammarVocabulary::create([
                                'meeting_number' => 5,
                                'section' => $sectionKey,
                                'word' => $ind,
                                'translation' => $eng,
                                'pos' => 'general' // Default
                            ]);
                        }
                    }
                }
            }
        }

        return "Migration Complete";
    }

    public function meeting5()
    {
        // Auto-migration disabled - data should be seeded manually via seeders
        // The migration method references undefined properties ($meeting5Questions, $meeting5Matrix, $meeting5Vocabularies)
        // Data already exists in database from seeders
        
        // Check if migration is needed (auto-migrate if empty)
        // $qCount = \App\Models\GrammarQuestion::where('meeting_number', 5)->count();
        // if ($qCount == 0) {
        //     $this->migrateMeeting5Data();
        // }

        $submitted = session('meeting5_submitted', false);
        $results = session('meeting5_results', []);
        $finalScore = session('meeting5_final_score', 0);
        $userAnswers = session('meeting5_user_answers', []);

        // Fetch Questions (Sentences)
        $questions = \App\Models\GrammarQuestion::where('meeting_number', 5)
            ->where('section', 'sentences')
            ->orderBy('question_number')
            ->get()
            ->mapWithKeys(function ($q) {
                return [$q->question_number => [
                    'id' => $q->question_text,
                    'en' => $q->correct_answer,
                    'tense' => $q->tense,
                    'db_id' => $q->id
                ]];
            });

        // Fetch Matrix
        $matrixQuestions = \App\Models\GrammarQuestion::where('meeting_number', 5)
            ->where('section', 'matrix')
            ->get();
        
        // Reconstruct Matrix Array with DB IDs
        $matrix = [];
        // Initialize structure with Tenses from matrixQuestions or hardcoded structure?
        // Using hardcoded structure to ensure all rows exist even if empty
        // Defined tenses structure
        $tenses = [
            'Simple Present', 'Present Continuous', 'Present Perfect', 'Present Perfect Continuous',
            'Simple Past', 'Past Continuous', 'Past Perfect', 'Past Perfect Continuous',
            'Simple Future', 'Future Continuous', 'Future Perfect', 'Future Perfect Continuous',
            'Simple Past Future', 'Past Future Continuous', 'Past Future Perfect', 'Past Future Perfect Continuous',
            'Modal'
        ];
        foreach ($tenses as $tense) {
            $matrix[$tense] = [
                'verbal' => null, 
                'nominal' => null, 
                'passive' => null
            ];
        }
        
        foreach ($matrixQuestions as $q) {
            $matrix[$q->tense][$q->structure] = [
                'id' => $q->question_text,
                'en' => $q->correct_answer,
                'db_id' => $q->id
            ];
        }

        // Fetch Vocabularies
        $vocabRecords = \App\Models\GrammarVocabulary::where('meeting_number', 5)->get();
        $vocabularies = [];
        foreach ($vocabRecords as $v) {
            // Section format: "Tense - Type"
            $parts = explode(' - ', $v->section);
            if (count($parts) >= 2) {
                $type = array_pop($parts);
                $tense = implode(' - ', $parts); // Rejoin in case tense has hyphen? Unlikely but safe.
                
                $vocabularies[$tense][$type][] = [
                    'ind' => $v->word,
                    'en' => $v->translation,
                    'db_id' => $v->id
                ];
                // We don't have db_id in the view loop traditionally, but for CRUD we need it?
                // The current view loop is: @foreach($vocabularies[$data['tense']]['verbal'] as $ind => $eng)
                // It doesn't use ID. I need to change the structure if I want to edit specific vocabs.
                // For now, let's keep the structure compatible with the view.
                // I will need to update the view to handle object or array with ID if I want to edit.
                // BUT, for now let's just match the old structure to get the page rendering.
            }
        }
        
        // Structure for Editing (Separate variable? Or modify main structure?)
        // The view currently expects [ind => eng]
        // If I change it to [ind => ['en' => eng, 'id' => db_id]], the view breaks.
        // So I must update the view concurrently.
        // Or I can update the view later.
        // Let's pass a separate variable $vocabulariesForView if needed, or just $vocabularies as [ind => eng] 
        // to pass verification first.
        
        // UPDATE: The user wants CRUD. So I MUST allow editing. 
        // I should probably return a richer structure and update the View immediately?
        // Let's pass $vocabulariesRaw or similar if I don't want to break things yet.
        // But the plan says "Update loops to work with DB objects".
        // So I will make the view robust entough.
        
        // For now, let's keep it simple to verify migration.
        // I will use `mapWithKeys` to allow editing later, or correct it in the view.
        // Let's stick to the OLD structure for now to ensure I don't break the page, 
        // and then I will update the view in the next step.
        
        // Fetch PR Questions
        $prQuestions = \App\Models\GrammarQuestion::where('meeting_number', 5)
            ->where('section', 'pr')
            ->get()
            ->map(function($q) {
                // Parse example (format: "ID|EN")
                $exampleParts = explode('|', $q->example ?? '');
                $example = [
                    'id' => $exampleParts[0] ?? '',
                    'en' => $exampleParts[1] ?? ''
                ];
                
                // Parse vocabulary JSON
                $vocab = json_decode($q->vocabulary ?? '{}', true);
                
                return [
                    'id' => $q->question_text,
                    'en' => $q->correct_answer,
                    'tense' => $q->tense,
                    'example' => $example,
                    'vocabulary' => $vocab,
                    'db_id' => $q->id
                ];
            });

        return view('assignments.grammar-writing.meeting5', [
            'questions' => $questions,
            'matrix' => $matrix,
            'prQuestions' => $prQuestions,
            'submitted' => $submitted,
            'results' => $results,
            'finalScore' => $finalScore,
            'userAnswers' => $userAnswers,
            'tenseExamples' => $this->meeting5TenseExamples,
            'vocabularies' => $vocabularies
        ]);
    }

    public function meeting5Submit(Request $request)
    {
        $userAnswers = $request->input('userAnswers', []);
        $results = [];
        $totalScore = 0;
        $totalItems = 0;

        // Fetch questions from database
        $sentenceQuestions = \App\Models\GrammarQuestion::where('meeting_number', 5)
            ->where('section', 'sentences')
            ->get();
        
        $matrixQuestions = \App\Models\GrammarQuestion::where('meeting_number', 5)
            ->where('section', 'matrix')
            ->get();
        
        $prQuestions = \App\Models\GrammarQuestion::where('meeting_number', 5)
            ->where('section', 'pr')
            ->get();

        // 1. Process Sentence Questions
        foreach ($sentenceQuestions as $q) {
            $questionKey = $q->question_number;
            $uTrans = trim($userAnswers['sentences'][$questionKey] ?? '');
            
            // Support multiple correct answers
            $variants = explode('|', $q->correct_answer);
            $bestScore = 0;
            $bestFormatted = '';
            
            foreach ($variants as $variant) {
                $variant = trim($variant);
                $correctWords = preg_split('/\s+/', $variant, -1, PREG_SPLIT_NO_EMPTY);
                $userWords = preg_split('/\s+/', $uTrans, -1, PREG_SPLIT_NO_EMPTY);
                
                $matchCount = 0;
                foreach ($userWords as $uw) {
                    foreach ($correctWords as $cw) {
                        if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                            $matchCount++;
                            break; 
                        }
                    }
                }
                
                $score = 0;
                if (count($correctWords) > 0) {
                    $ratio = $matchCount / count($correctWords);
                    $score = round($ratio * 100);
                }
                
                if ($score > $bestScore) {
                    $bestScore = $score;
                    $bestFormatted = $this->getDiffFeedback($userWords, $correctWords);
                }
            }

            $results['sentences'][$questionKey] = [
                'user_answer' => $uTrans,
                'score' => $bestScore,
                'formatted_answer' => $bestFormatted,
                'correct_answer' => $q->correct_answer
            ];
            
            $totalScore += $bestScore;
            $totalItems++;
        }

        // 2. Process Matrix Questions
        foreach ($matrixQuestions as $q) {
            $key = str_replace(' ', '_', strtolower($q->tense)) . '_' . $q->structure;
            $uTrans = trim($userAnswers['matrix'][$key] ?? '');
            
            // Support multiple correct answers
            $variants = explode('|', $q->correct_answer);
            $bestScore = 0;
            $bestFormatted = '';
            
            foreach ($variants as $variant) {
                $variant = trim($variant);
                $correctWords = preg_split('/\s+/', $variant, -1, PREG_SPLIT_NO_EMPTY);
                $userWords = preg_split('/\s+/', $uTrans, -1, PREG_SPLIT_NO_EMPTY);
                
                $matchCount = 0;
                foreach ($userWords as $uw) {
                    foreach ($correctWords as $cw) {
                        if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                            $matchCount++;
                            break; 
                        }
                    }
                }
                
                $score = 0;
                if (count($correctWords) > 0) {
                    $ratio = $matchCount / count($correctWords);
                    $score = round($ratio * 100);
                }
                
                if ($score > $bestScore) {
                    $bestScore = $score;
                    $bestFormatted = $this->getDiffFeedback($userWords, $correctWords);
                }
            }

            $results['matrix'][$q->tense][$q->structure] = [
                'user_answer' => $uTrans,
                'score' => $bestScore,
                'formatted_answer' => $bestFormatted,
                'correct_answer' => $q->correct_answer
            ];
            
            $totalScore += $bestScore;
            $totalItems++;
        }
        
        // 3. Process PR Questions
        $prIndex = 0;
        foreach ($prQuestions as $q) {
            $uTrans = trim($userAnswers['pr'][$prIndex] ?? '');
            
            // Support multiple correct answers
            $variants = explode('|', $q->correct_answer);
            $bestScore = 0;
            $bestFormatted = '';
            
            foreach ($variants as $variant) {
                $variant = trim($variant);
                $correctWords = preg_split('/\s+/', $variant, -1, PREG_SPLIT_NO_EMPTY);
                $userWords = preg_split('/\s+/', $uTrans, -1, PREG_SPLIT_NO_EMPTY);
                
                $matchCount = 0;
                foreach ($userWords as $uw) {
                    foreach ($correctWords as $cw) {
                        if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                            $matchCount++;
                            break; 
                        }
                    }
                }
                
                $score = 0;
                if (count($correctWords) > 0) {
                    $ratio = $matchCount / count($correctWords);
                    $score = round($ratio * 100);
                }
                
                if ($score > $bestScore) {
                    $bestScore = $score;
                    $bestFormatted = $this->getDiffFeedback($userWords, $correctWords);
                }
            }

            $results['pr'][$prIndex] = [
                'user_answer' => $uTrans,
                'score' => $bestScore,
                'formatted_answer' => $bestFormatted,
                'correct_answer' => $q->correct_answer
            ];
            
            $totalScore += $bestScore;
            $totalItems++;
            $prIndex++;
        }


        // Calculate Final Score
        $finalScore = ($totalItems > 0) ? round($totalScore / $totalItems) : 0;

        session([
            'meeting5_submitted' => true,
            'meeting5_results' => $results,
            'meeting5_final_score' => $finalScore,
            'meeting5_user_answers' => $userAnswers
        ]);

        // Save score to database
        $this->saveMeetingScore(5, $finalScore);

        return redirect()->route('assignments.grammar-writing.meeting5');
    }

    public function meeting5Reset()
    {
        session()->forget([
            'meeting5_submitted', 
            'meeting5_results', 
            'meeting5_final_score', 
            'meeting5_user_answers'
        ]);
        return redirect()->route('assignments.grammar-writing.meeting5');
    }

