    private function getMeeting6DataFromDB()
    {
        $questions = \App\Models\GrammarQuestion::where('meeting_number', 6)->orderBy('question_number')->get();
        
        $verbPatterns = [];
        $toInfinitive = [];
        $gerund = [];
        $paragraph = null;

        foreach ($questions as $q) {
            $item = [
                'db_id' => $q->id,
                'id' => $q->question_text,
                'en' => $q->correct_answer,
                'example' => $q->example,
                'vocab' => $q->vocab,
                'section' => $q->section
            ];

            if ($q->section === 'verb_patterns') {
                $verbPatterns[$q->question_number] = $item;
            } elseif ($q->section === 'to_infinitive') {
                $toInfinitive[$q->question_number] = $item;
            } elseif ($q->section === 'gerund') {
                $gerund[$q->question_number] = $item;
            } elseif ($q->section === 'paragraph') {
                $paragraph = $item;
            }
        }
        
        return [$verbPatterns, $toInfinitive, $gerund, $paragraph];
    }

    public function meeting6()
    {
        list($verbPatterns, $toInfinitive, $gerund, $paragraph) = $this->getMeeting6DataFromDB();

        $submitted = session('meeting6_submitted', false);
        $results = session('meeting6_results', []);
        $finalScore = session('meeting6_final_score', 0);
        $userAnswers = session('meeting6_user_answers', []);

        return view('assignments.grammar-writing.meeting6', [
            'verbPatterns' => $verbPatterns,
            'toInfinitive' => $toInfinitive,
            'gerund' => $gerund,
            'paragraph' => $paragraph,
            'submitted' => $submitted,
            'results' => $results,
            'finalScore' => $finalScore,
            'userAnswers' => $userAnswers
        ]);
    }

    public function meeting6Submit(Request $request)
    {
        list($verbPatterns, $toInfinitive, $gerund, $paragraph) = $this->getMeeting6DataFromDB();

        $userAnswers = $request->input('userAnswers', []);
        $results = [];
        $totalScore = 0;
        $totalItems = 0;

        // 1. Process Verb Patterns
        foreach ($verbPatterns as $idx => $data) {
            $uTrans = trim($userAnswers['verbPatterns'][$idx] ?? '');
            
            $correctWords = preg_split('/\s+/', $data['en'], -1, PREG_SPLIT_NO_EMPTY);
            $userWords = preg_split('/\s+/', $uTrans, -1, PREG_SPLIT_NO_EMPTY);
            
            $matchCount = 0;
            foreach ($userWords as $uw) {
                foreach ($correctWords as $cw) {
                    if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                        $matchCount++;
                        break; 
                    }
                }
            }
            
            $score = 0;
            if (count($correctWords) > 0) {
                $ratio = $matchCount / count($correctWords);
                $score = round($ratio * 100);
            }
            
            $formattedAnswer = $this->getDiffFeedback($userWords, $correctWords);

            $results['verbPatterns'][$idx] = [
                'user_answer' => $uTrans,
                'score' => $score,
                'formatted_answer' => $formattedAnswer,
                'correct_answer' => $data['en']
            ];
            
            $totalScore += $score;
            $totalItems++;
        }

        // 2. Process To Infinitive
        foreach ($toInfinitive as $idx => $data) {
            $uTrans = trim($userAnswers['toInfinitive'][$idx] ?? '');
            
            $correctWords = preg_split('/\s+/', $data['en'], -1, PREG_SPLIT_NO_EMPTY);
            $userWords = preg_split('/\s+/', $uTrans, -1, PREG_SPLIT_NO_EMPTY);
            
            $matchCount = 0;
            foreach ($userWords as $uw) {
                foreach ($correctWords as $cw) {
                    if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                        $matchCount++;
                        break; 
                    }
                }
            }
            
            $score = 0;
            if (count($correctWords) > 0) {
                $ratio = $matchCount / count($correctWords);
                $score = round($ratio * 100);
            }
            
            $formattedAnswer = $this->getDiffFeedback($userWords, $correctWords);

            $results['toInfinitive'][$idx] = [
                'user_answer' => $uTrans,
                'score' => $score,
                'formatted_answer' => $formattedAnswer,
                'correct_answer' => $data['en']
            ];
            
            $totalScore += $score;
            $totalItems++;
        }

        // 3. Process Gerund
        foreach ($gerund as $idx => $data) {
            $uTrans = trim($userAnswers['gerund'][$idx] ?? '');
            
            $correctWords = preg_split('/\s+/', $data['en'], -1, PREG_SPLIT_NO_EMPTY);
            $userWords = preg_split('/\s+/', $uTrans, -1, PREG_SPLIT_NO_EMPTY);
            
            $matchCount = 0;
            foreach ($userWords as $uw) {
                foreach ($correctWords as $cw) {
                    if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                        $matchCount++;
                        break; 
                    }
                }
            }
            
            $score = 0;
            if (count($correctWords) > 0) {
                $ratio = $matchCount / count($correctWords);
                $score = round($ratio * 100);
            }
            
            $formattedAnswer = $this->getDiffFeedback($userWords, $correctWords);

            $results['gerund'][$idx] = [
                'user_answer' => $uTrans,
                'score' => $score,
                'formatted_answer' => $formattedAnswer,
                'correct_answer' => $data['en']
            ];
            
            $totalScore += $score;
            $totalItems++;
        }

        // 4. Process Paragraph
        $uTrans = trim($userAnswers['paragraph'] ?? '');
        
        $correctWords = preg_split('/\s+/', $paragraph['en'], -1, PREG_SPLIT_NO_EMPTY);
        $userWords = preg_split('/\s+/', $uTrans, -1, PREG_SPLIT_NO_EMPTY);
        
        $matchCount = 0;
        foreach ($userWords as $uw) {
            foreach ($correctWords as $cw) {
                if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                    $matchCount++;
                    break; 
                }
            }
        }
        
        $score = 0;
        if (count($correctWords) > 0) {
            $ratio = $matchCount / count($correctWords);
            $score = round($ratio * 100);
        }
        
        $formattedAnswer = $this->getDiffFeedback($userWords, $correctWords);

        $results['paragraph'] = [
            'user_answer' => $uTrans,
            'score' => $score,
            'formatted_answer' => $formattedAnswer,
            'correct_answer' => $paragraph['en']
        ];
        
        $totalScore += $score;
        $totalItems++;

        // Calculate Final Score
        $finalScore = ($totalItems > 0) ? round($totalScore / $totalItems) : 0;

        session([
            'meeting6_submitted' => true,
            'meeting6_results' => $results,
            'meeting6_final_score' => $finalScore,
            'meeting6_user_answers' => $userAnswers
        ]);

        // Save score to database
        $this->saveMeetingScore(6, $finalScore);

        return redirect()->route('assignments.grammar-writing.meeting6');
    }

