    public function meeting8Submit(Request $request)
    {
        list($questions, $paragraph) = $this->getMeeting8DataFromDB();

        $userAnswers = $request->input('userAnswers', []);
        $userParagraphAnswer = $request->input('userParagraphAnswer', '');
        
        $results = [];
        $totalScore = 0;
        // Max score calculation: Questions 80%, Paragraph 20%
        // But to keep it simple and consistent with view showing ?/10, we calculate per item.
        // Let's stick to the M8 weighted logic:
        // Final = (AvgQuestionScore * 0.8) + (ParagraphScore * 0.2)
        // Where scores are 0-100.
        
        $questionTotalScore = 0;
        $totalItems = count($questions);

        foreach ($questions as $idx => $data) {
            $uTrans = trim($userAnswers[$idx] ?? '');
            
            $correctWords = preg_split('/\s+/', $data['en'], -1, PREG_SPLIT_NO_EMPTY);
            $userWords = preg_split('/\s+/', $uTrans, -1, PREG_SPLIT_NO_EMPTY);
            
            $matchCount = 0;
            foreach ($userWords as $uw) {
                foreach ($correctWords as $cw) {
                    if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                        $matchCount++;
                        break; 
                    }
                }
            }
            
            // Calculate 0-10 score
            $score = 0;
            if (count($correctWords) > 0) {
                $ratio = $matchCount / count($correctWords);
                $score = round($ratio * 10);
            }
            
            $formattedAnswer = $this->getDiffFeedback($userWords, $correctWords);

            $results[$idx] = [
                'user_answer' => $uTrans,
                'score' => $score, // 0-10
                'formatted_answer' => $formattedAnswer,
                'correct_answer' => $data['en']
            ];
            
            // Convert to 100 scale for weighted calculation
            $questionTotalScore += ($score * 10);
        }

        $avgQuestionScore = ($totalItems > 0) ? ($questionTotalScore / $totalItems) : 0;

        // Check Paragraph
        $paraCorrectWords = preg_split('/\s+/', $paragraph['en'], -1, PREG_SPLIT_NO_EMPTY);
        $paraUserWords = preg_split('/\s+/', $userParagraphAnswer, -1, PREG_SPLIT_NO_EMPTY);
        
        $paraMatchCount = 0;
        foreach ($paraUserWords as $uw) {
            foreach ($paraCorrectWords as $cw) {
                if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                    $paraMatchCount++;
                    break;
                }
            }
        }
        
        // Paragraph score 0-100
        $paraScore100 = 0;
        if (count($paraCorrectWords) > 0) {
            $ratio = $paraMatchCount / count($paraCorrectWords);
            $paraScore100 = round($ratio * 100);
        }
        
        $paraFormatted = $this->getDiffFeedback($paraUserWords, $paraCorrectWords);

        // Final Weighting
        $finalScore = round(($avgQuestionScore * 0.8) + ($paraScore100 * 0.2));

        session([
            'meeting8_submitted' => true,
            'meeting8_results' => $results,
            'meeting8_paragraph_result' => [
                'score' => $paraScore100,
                'max_score' => 100, // View expects this
                'formatted_answer' => $paraFormatted
            ],
            'meeting8_final_score' => $finalScore,
            'meeting8_user_answers' => $userAnswers,
            'meeting8_user_paragraph_answer' => $userParagraphAnswer
        ]);

        // Save score to database
        $this->saveMeetingScore(8, $finalScore);

        return redirect()->route('assignments.grammar-writing.meeting8');
    }

    public function meeting8Reset()
    {
        session()->forget([
            'meeting8_submitted', 
            'meeting8_results', 
            'meeting8_paragraph_result',
            'meeting8_final_score', 
            'meeting8_user_answers',
            'meeting8_user_paragraph_answer'
        ]);
        return redirect()->route('assignments.grammar-writing.meeting8');
    }

