    private $meeting10Vocab = [];

    public function meeting10()
    {
        $submitted = session('meeting10_submitted', false);
        $results = session('meeting10_results', []);
        $paragraphResult = session('meeting10_paragraph_result', []);
        $finalScore = session('meeting10_final_score', 0);
        $userAnswers = session('meeting10_user_answers', []);
        $userParagraphAnswer = session('meeting10_user_paragraph_answer', '');

        // Fetch questions from DB
        $questions = \App\Models\GrammarQuestion::where('meeting_number', 10)
            ->where('section', '!=', 'paragraph') // ensure explicit check though current questions are likely assumed not paragraph
            ->orderBy('question_number')
            ->get()
            ->map(function($q) {
                return [
                    'id' => $q->question_text,
                    'en' => $q->correct_answer,
                    'type' => $q->structure,
                    'vocab' => $q->vocab,
                    'example' => [
                        'id' => $q->example_id,
                        'en' => $q->example_en
                    ],
                    'db_id' => $q->id
                ];
            });

        // Fetch Paragraph from DB
        $paragraphParams = \App\Models\GrammarQuestion::where('meeting_number', 10)
                                    ->where('section', 'paragraph')
                                    ->first();

        if ($paragraphParams) {
            $paragraph = [
                'id' => $paragraphParams->question_text,
                'en' => $paragraphParams->correct_answer,
                'vocab' => $paragraphParams->vocab,
                'db_id' => $paragraphParams->id
            ];
        } else {
            $paragraph = [
                'id' => $this->meeting10Paragraph['id'],
                'en' => $this->meeting10Paragraph['en'],
                'vocab' => $this->meeting10Paragraph['vocab'],
                'db_id' => null
            ];
        }

        return view('assignments.grammar-writing.meeting10', [
            'questions' => $questions,
            'paragraph' => $paragraph,
            'fullParagraphId' => $paragraph['id'], // Legacy variable for existing view logic
            'fullParagraphEn' => $paragraph['en'],
            'paragraphVocab' => $paragraph['vocab'],
            'examples' => $this->meeting10Examples,
            'submitted' => $submitted,
            'results' => $results,
            'paragraphResult' => $paragraphResult,
            'finalScore' => $finalScore,
            'userAnswers' => $userAnswers,
            'userParagraphAnswer' => $userParagraphAnswer
        ]);
    }

    public function meeting10Submit(Request $request)
    {
        $userAnswers = $request->input('userAnswers', []);
        $userParagraphAnswer = $request->input('userParagraphAnswer', '');
        
        // Fetch questions from DB for scoring
        $dbQuestions = \App\Models\GrammarQuestion::where('meeting_number', 10)
            ->where('section', '!=', 'paragraph') 
            ->orderBy('question_number')
            ->get()
            // ... (keep map logic if needed, but collection is simpler)
            ->map(function($q) {
                 return [
                    'id' => $q->question_text,
                    'en' => $q->correct_answer,
                    // other fields not strictly needed for scoring but consistent with strucutre
                    'db_id' => $q->id
                 ];
            });

        // Fetch Paragraph for scoring
        $paragraphParams = \App\Models\GrammarQuestion::where('meeting_number', 10)
                                    ->where('section', 'paragraph')
                                    ->first();
        $paragraphEn = $paragraphParams ? $paragraphParams->correct_answer : $this->meeting10Paragraph['en'];

        $results = [];
        $totalScore = 0;
        $maxScore = ($dbQuestions->count() * 10) + 20;

        foreach ($dbQuestions as $idx => $data) {
            $uTrans = trim($userAnswers[$idx] ?? '');
            
            $correctWords = preg_split('/\s+/', $data['en'], -1, PREG_SPLIT_NO_EMPTY);
            $userWords = preg_split('/\s+/', $uTrans, -1, PREG_SPLIT_NO_EMPTY);
            
            $matchCount = 0;
            foreach ($userWords as $uw) {
                foreach ($correctWords as $cw) {
                    if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                        $matchCount++;
                        break; 
                    }
                }
            }
            
            $score = 0;
            if (count($correctWords) > 0) {
                $ratio = $matchCount / count($correctWords);
                $score = round($ratio * 10);
            }
            
            $formattedAnswer = $this->getDiffFeedback($userWords, $correctWords);

            $results[$idx] = [
                'user_answer' => $uTrans,
                'score' => $score,
                'formatted_answer' => $formattedAnswer,
                'correct_answer' => $data['en']
            ];
            
            $totalScore += $score;
        }

        $paraCorrectWords = preg_split('/\s+/', $this->meeting10Paragraph['en'], -1, PREG_SPLIT_NO_EMPTY);
        $paraUserWords = preg_split('/\s+/', $userParagraphAnswer, -1, PREG_SPLIT_NO_EMPTY);
        
        $paraMatchCount = 0;
        foreach ($paraUserWords as $uw) {
            foreach ($paraCorrectWords as $cw) {
                if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                    $paraMatchCount++;
                    break;
                }
            }
        }
        
        $paraScore = 0;
        if (count($paraCorrectWords) > 0) {
            $ratio = $paraMatchCount / count($paraCorrectWords);
            $paraScore = round($ratio * 20);
        }
        
        $paraFormatted = $this->getDiffFeedback($paraUserWords, $paraCorrectWords);
        $totalScore += $paraScore;
        
        $finalScore = round(($totalScore / $maxScore) * 100);

        session([
            'meeting10_submitted' => true,
            'meeting10_results' => $results,
            'meeting10_paragraph_result' => [
                'score' => $paraScore,
                'max_score' => 20,
                'formatted_answer' => $paraFormatted
            ],
            'meeting10_final_score' => $finalScore,
            'meeting10_user_answers' => $userAnswers,
            'meeting10_user_paragraph_answer' => $userParagraphAnswer
        ]);

        // Save score to database
        $this->saveMeetingScore(10, $finalScore);

        return redirect()->route('assignments.grammar-writing.meeting10');
    }

    public function meeting10Reset()
    {
        session()->forget([
            'meeting10_submitted', 
            'meeting10_results', 
            'meeting10_paragraph_result', 
            'meeting10_final_score', 
            'meeting10_user_answers', 
            'meeting10_user_paragraph_answer'
        ]);
        return redirect()->route('assignments.grammar-writing.meeting10');
    }

