    public function meeting11()
    {
        $submitted = session('meeting11_submitted', false);
        $results = session('meeting11_results', []);
        $paragraphResult = session('meeting11_paragraph_result', []);
        $finalScore = session('meeting11_final_score', 0);
        $userAnswers = session('meeting11_user_answers', []);
        $userParagraphAnswer = session('meeting11_user_paragraph_answer', '');

        // Fetch questions from DB
                $questions = \App\Models\GrammarQuestion::where('meeting_number', 11)
            ->where(function($q) {
                $q->whereNull('section')
                  ->orWhere('section', '!=', 'paragraph');
            })
            ->orderBy('question_number')
            ->get()
            ->map(function($q) {
                return [
                    'id' => $q->question_text,
                    'en' => $q->correct_answer,
                    'vocab' => $q->vocab,
                    'example' => $q->example_en,
                    'db_id' => $q->id
                ];
            });

        if ($questions->isEmpty()) {
            $questions = collect($this->meeting11Questions)->map(function ($q) {
                return [
                    'id' => $q['id'],
                    'en' => $q['en'],
                    'vocab' => $q['vocab'] ?? [],
                    'example' => $q['example'] ?? '',
                    'db_id' => null,
                ];
            })->values();
        }

        // Fetch Paragraph from DB
        $dbParagraph = \App\Models\GrammarQuestion::where('meeting_number', 11)
            ->where('section', 'paragraph')
            ->first();

        // Fallback or use DB data
        $paragraphId = $dbParagraph ? $dbParagraph->question_text : $this->meeting11Paragraph['id'];
        $paragraphEn = $dbParagraph ? $dbParagraph->correct_answer : $this->meeting11Paragraph['en'];
        $paragraphVocab = $dbParagraph ? ($dbParagraph->vocab ?? []) : ($this->meeting11Paragraph['vocab'] ?? []);
        $paragraphDbId = $dbParagraph ? $dbParagraph->id : null;

        return view('assignments.grammar-writing.meeting11', [
            'questions' => $questions,
            'fullParagraphId' => $paragraphId,
            'fullParagraphEn' => $paragraphEn,
            'paragraphVocab' => $paragraphVocab,
            'paragraphDbId' => $paragraphDbId, // Pass DB ID for edit/delete
            'submitted' => $submitted,
            'results' => $results,
            'paragraphResult' => $paragraphResult,
            'finalScore' => $finalScore,
            'userAnswers' => $userAnswers,
            'userParagraphAnswer' => $userParagraphAnswer
        ]);
    }

    public function meeting11Submit(Request $request)
    {
        $userAnswers = $request->input('userAnswers', []);
        $userParagraphAnswer = $request->input('userParagraphAnswer', '');
        
        // Fetch questions from DB for scoring
                $dbQuestions = \App\Models\GrammarQuestion::where('meeting_number', 11)
            ->where(function($q) {
                $q->whereNull('section')
                  ->orWhere('section', '!=', 'paragraph');
            })
            ->orderBy('question_number')
            ->get()
            ->map(function($q) {
                 return [
                    'id' => $q->question_text,
                    'en' => $q->correct_answer,
                    'db_id' => $q->id
                 ];
            });

        if ($dbQuestions->isEmpty()) {
            $dbQuestions = collect($this->meeting11Questions)->values()->map(function ($q) {
                return [
                    'id' => $q['id'],
                    'en' => $q['en'],
                    'db_id' => null,
                ];
            });
        }

        $results = [];
        $totalScore = 0;
        $maxScore = ($dbQuestions->count() * 10) + 20;

        foreach ($dbQuestions as $idx => $data) {
            $uTrans = trim($userAnswers[$idx] ?? '');
            
            $correctWords = preg_split('/\s+/', $data['en'], -1, PREG_SPLIT_NO_EMPTY);
            $userWords = preg_split('/\s+/', $uTrans, -1, PREG_SPLIT_NO_EMPTY);
            
            $matchCount = 0;
            foreach ($userWords as $uw) {
                foreach ($correctWords as $cw) {
                    if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                        $matchCount++;
                        break; 
                    }
                }
            }
            
            $score = 0;
            if (count($correctWords) > 0) {
                $ratio = $matchCount / count($correctWords);
                $score = round($ratio * 10);
            }
            
            $formattedAnswer = $this->getDiffFeedback($userWords, $correctWords);

            $results[$idx] = [
                'user_answer' => $uTrans,
                'score' => $score,
                'formatted_answer' => $formattedAnswer,
                'correct_answer' => $data['en']
            ];
            
            $totalScore += $score;
        }

        $dbParagraph = \App\Models\GrammarQuestion::where('meeting_number', 11)
            ->where('section', 'paragraph')
            ->first();

        $paragraphCorrectAnswer = $dbParagraph ? $dbParagraph->correct_answer : $this->meeting11Paragraph['en'];
        $paraCorrectWords = preg_split('/\s+/', $paragraphCorrectAnswer, -1, PREG_SPLIT_NO_EMPTY);
        $paraUserWords = preg_split('/\s+/', $userParagraphAnswer, -1, PREG_SPLIT_NO_EMPTY);
        
        $paraMatchCount = 0;
        foreach ($paraUserWords as $uw) {
            foreach ($paraCorrectWords as $cw) {
                if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                    $paraMatchCount++;
                    break;
                }
            }
        }
        
        $paraScore = 0;
        if (count($paraCorrectWords) > 0) {
            $ratio = $paraMatchCount / count($paraCorrectWords);
            $paraScore = round($ratio * 20);
        }
        
        $paraFormatted = $this->getDiffFeedback($paraUserWords, $paraCorrectWords);
        $totalScore += $paraScore;
        
        $finalScore = $maxScore > 0 ? round(($totalScore / $maxScore) * 100) : 0;

        session([
            'meeting11_submitted' => true,
            'meeting11_results' => $results,
            'meeting11_paragraph_result' => [
                'score' => $paraScore,
                'max_score' => 20,
                'formatted_answer' => $paraFormatted
            ],
            'meeting11_final_score' => $finalScore,
            'meeting11_user_answers' => $userAnswers,
            'meeting11_user_paragraph_answer' => $userParagraphAnswer
        ]);

        // Save score to database
        $this->saveMeetingScore(11, $finalScore);

        return redirect()->route('assignments.grammar-writing.meeting11');
    }

    public function meeting11Reset()
    {
        session()->forget([
            'meeting11_submitted', 
            'meeting11_results', 
            'meeting11_paragraph_result', 
            'meeting11_final_score', 
            'meeting11_user_answers', 
            'meeting11_user_paragraph_answer'
        ]);
        return redirect()->route('assignments.grammar-writing.meeting11');
    }

