    public function meeting12()
    {
        $submitted = session('meeting12_submitted', false);
        $results = session('meeting12_results', []);
        $paragraphResult = session('meeting12_paragraph_result', []);
        $finalScore = session('meeting12_final_score', 0);
        $userAnswers = session('meeting12_user_answers', []);
        $userParagraphAnswer = session('meeting12_user_paragraph_answer', '');

        // Fetch questions from DB
                $questions = \App\Models\GrammarQuestion::where('meeting_number', 12)
            ->where(function($q) {
                $q->whereNull('section')
                  ->orWhere('section', '!=', 'paragraph');
            })
            ->orderBy('question_number')
            ->get()
            ->map(function($q) {
                return [
                    'id' => $q->question_text,
                    'en' => $q->correct_answer,
                    'type' => $q->structure,
                    'conjunction' => $q->formula,
                    'example' => $q->example, // Array cast
                    'vocab' => $q->vocab,
                    'db_id' => $q->id
                ];
            });

        if ($questions->isEmpty()) {
            $questions = collect($this->meeting12Questions)->values()->map(function ($q) {
                return [
                    'id' => $q['id'],
                    'en' => $q['en'],
                    'type' => $q['type'] ?? '',
                    'conjunction' => $q['conjunction'] ?? '',
                    'example' => $q['example'] ?? ['id' => '', 'en' => ''],
                    'vocab' => $q['vocab'] ?? [],
                    'db_id' => null,
                ];
            });
        }

        // Fetch Paragraph from DB
        $dbParagraph = \App\Models\GrammarQuestion::where('meeting_number', 12)
            ->where('section', 'paragraph')
            ->first();

        $paragraphId = $dbParagraph ? $dbParagraph->question_text : $this->meeting12Paragraph['id'];
        $paragraphEn = $dbParagraph ? $dbParagraph->correct_answer : $this->meeting12Paragraph['en'];
        $paragraphVocab = $dbParagraph ? ($dbParagraph->vocab ?? []) : ($this->meeting12Paragraph['vocab'] ?? []);
        $paragraphDbId = $dbParagraph ? $dbParagraph->id : null;

        return view('assignments.grammar-writing.meeting12', [
            'questions' => $questions,
            'fullParagraphId' => $paragraphId,
            'fullParagraphEn' => $paragraphEn,
            'paragraphVocab' => $paragraphVocab,
            'paragraphDbId' => $paragraphDbId,
            'submitted' => $submitted,
            'results' => $results,
            'paragraphResult' => $paragraphResult,
            'finalScore' => $finalScore,
            'userAnswers' => $userAnswers,
            'userParagraphAnswer' => $userParagraphAnswer
        ]);
    }

    public function meeting12Submit(Request $request)
    {
        $userAnswers = $request->input('userAnswers', []);
        $userParagraphAnswer = $request->input('userParagraphAnswer', '');
        
        // Fetch questions from DB for scoring
                $dbQuestions = \App\Models\GrammarQuestion::where('meeting_number', 12)
            ->where(function($q) {
                $q->whereNull('section')
                  ->orWhere('section', '!=', 'paragraph');
            })
            ->orderBy('question_number')
            ->get()
            ->map(function($q) {
                 return [
                    'id' => $q->question_text,
                    'en' => $q->correct_answer,
                    'db_id' => $q->id
                 ];
            });

        if ($dbQuestions->isEmpty()) {
            $dbQuestions = collect($this->meeting12Questions)->values()->map(function ($q) {
                return [
                    'id' => $q['id'],
                    'en' => $q['en'],
                    'db_id' => null,
                ];
            });
        }

        $results = [];
        $totalScore = 0;
        $maxScore = ($dbQuestions->count() * 10) + 20;

        foreach ($dbQuestions as $idx => $data) {
            $uTrans = trim($userAnswers[$idx] ?? '');
            
            $correctWords = preg_split('/\s+/', $data['en'], -1, PREG_SPLIT_NO_EMPTY);
            $userWords = preg_split('/\s+/', $uTrans, -1, PREG_SPLIT_NO_EMPTY);
            
            $matchCount = 0;
            foreach ($userWords as $uw) {
                foreach ($correctWords as $cw) {
                    if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                        $matchCount++;
                        break; 
                    }
                }
            }
            
            $score = 0;
            if (count($correctWords) > 0) {
                $ratio = $matchCount / count($correctWords);
                $score = round($ratio * 10);
            }
            
            $formattedAnswer = $this->getDiffFeedback($userWords, $correctWords);

            $results[$idx] = [
                'user_answer' => $uTrans,
                'score' => $score,
                'formatted_answer' => $formattedAnswer,
                'correct_answer' => $data['en']
            ];
            
            $totalScore += $score;
        }
        
        $dbParagraph = \App\Models\GrammarQuestion::where('meeting_number', 12)
            ->where('section', 'paragraph')
            ->first();

        $paragraphCorrectAnswer = $dbParagraph ? $dbParagraph->correct_answer : $this->meeting12Paragraph['en'];
        $paraCorrectWords = preg_split('/\s+/', $paragraphCorrectAnswer, -1, PREG_SPLIT_NO_EMPTY);
        $paraUserWords = preg_split('/\s+/', $userParagraphAnswer, -1, PREG_SPLIT_NO_EMPTY);
        
        $paraMatchCount = 0;
        foreach ($paraUserWords as $uw) {
            foreach ($paraCorrectWords as $cw) {
                if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                    $paraMatchCount++;
                    break;
                }
            }
        }
        
        $paraScore = 0;
        if (count($paraCorrectWords) > 0) {
            $ratio = $paraMatchCount / count($paraCorrectWords);
            $paraScore = round($ratio * 20);
        }
        
        $paraFormatted = $this->getDiffFeedback($paraUserWords, $paraCorrectWords);
        $totalScore += $paraScore;
        
        $finalScore = $maxScore > 0 ? round(($totalScore / $maxScore) * 100) : 0;

        session([
            'meeting12_submitted' => true,
            'meeting12_results' => $results,
            'meeting12_paragraph_result' => [
                'score' => $paraScore,
                'max_score' => 20,
                'formatted_answer' => $paraFormatted
            ],
            'meeting12_final_score' => $finalScore,
            'meeting12_user_answers' => $userAnswers,
            'meeting12_user_paragraph_answer' => $userParagraphAnswer
        ]);

        // Save score to database
        $this->saveMeetingScore(12, $finalScore);

        return redirect()->route('assignments.grammar-writing.meeting12');
    }

    public function meeting12Reset()
    {
        session()->forget([
            'meeting12_submitted', 
            'meeting12_results', 
            'meeting12_paragraph_result', 
            'meeting12_final_score', 
            'meeting12_user_answers', 
            'meeting12_user_paragraph_answer'
        ]);
        return redirect()->route('assignments.grammar-writing.meeting12');
    }

