    public function meeting13()
    {
        $submitted = session('meeting13_submitted', false);
        $results = session('meeting13_results', []);
        $paragraphResult = session('meeting13_paragraph_result', []);
        $finalScore = session('meeting13_final_score', 0);
        $userAnswers = session('meeting13_user_answers', []);
        $userParagraphAnswer = session('meeting13_user_paragraph_answer', '');

        // Fetch questions from DB
        $questions = \App\Models\GrammarQuestion::where('meeting_number', 13)
            ->where(function($q) {
                $q->whereNull('section')->orWhere('section', '!=', 'paragraph');
            })
            ->orderBy('question_number')
            ->get()
            ->map(function($q) {
                return [
                    'id' => $q->question_text,
                    'en' => $q->correct_answer,
                    'vocab' => $q->vocab,
                    'example' => [
                        'id' => $q->example_id,
                        'en' => $q->example_en
                    ],
                    'db_id' => $q->id
                ];
            });

        // Fetch Paragraph from DB
        $dbParagraph = \App\Models\GrammarQuestion::where('meeting_number', 13)
            ->where('section', 'paragraph')
            ->first();

        $fullParagraphId = $dbParagraph ? $dbParagraph->question_text : $this->meeting13Paragraph['id'];
        $fullParagraphEn = $dbParagraph ? $dbParagraph->correct_answer : $this->meeting13Paragraph['en'];
        $paragraphVocab = $dbParagraph ? $dbParagraph->vocab : $this->meeting13Paragraph['vocab'];
        $paragraphDbId = $dbParagraph ? $dbParagraph->id : null;

        return view('assignments.grammar-writing.meeting13', [
            'questions' => $questions,
            'fullParagraphId' => $fullParagraphId,
            'fullParagraphEn' => $fullParagraphEn,
            'paragraphVocab' => $paragraphVocab,
            'paragraphDbId' => $paragraphDbId,
            'submitted' => $submitted,
            'results' => $results,
            'paragraphResult' => $paragraphResult,
            'finalScore' => $finalScore,
            'userAnswers' => $userAnswers,
            'userParagraphAnswer' => $userParagraphAnswer
        ]);
    }

    public function meeting13Submit(Request $request)
    {
        $userAnswers = $request->input('userAnswers', []);
        $userParagraphAnswer = $request->input('userParagraphAnswer', '');

        // Fetch questions from DB for scoring
        $dbQuestions = \App\Models\GrammarQuestion::where('meeting_number', 13)
            ->where(function($q) {
                $q->whereNull('section')->orWhere('section', '!=', 'paragraph');
            })
            ->orderBy('question_number')
            ->get()
            ->map(function($q) {
                return [
                    'en' => $q->correct_answer
                ];
            });
        
        $results = [];
        $totalScore = 0;
        $maxScore = ($dbQuestions->count() * 10) + 20;

        foreach ($dbQuestions as $idx => $data) {
            // Adjust index to match DB (DB is 1-based, array logic in view might be 0-based or 1-based depending on usage)
            // View uses $idx from $questions which is collection, so 0-based index if iterated, but let's check view foreach
            // View: @foreach($questions as $idx => $data). If $questions is collection, idx is 0,1,2...
            // $userAnswers is array from form.
            // We should use $idx from loop.
            // Wait, previous hardcoded array was 1-based (lines 5143, 5156...).
            // DB collection is 0-based by default.
            // If view uses key, we need to align.
            // DB results don't preserve 'question_number' as key unless keyedBy.
            // But $userAnswers usually keys by generic loop index.
            // If view iterates collection, keys are 0,1,2. 
            // Previous hardcoded: 1,2,3.
            // So $userAnswers might have keys 1,2,3 if old view used 1-based keys.
            // Let's check view loop. `@foreach($questions as $idx => $data)`. 
            // If $questions is mapped collection, keys are 0,1,2.
            // So $userAnswers keys will be 0,1,2.
            // But hardcoded used 1..20. The OLD view output $idx.
            // If I change to collection, keys become 0..19.
            // I should make sure scoring aligns.
            
            // To be safe, I can keyBy question_number if I want 1-based.
            // Or just rely on order. 
            // The submitted $userAnswers keys come from correct generation in view.
            
            $uTrans = trim($userAnswers[$idx] ?? ''); // If view generates 0-based component name, this matches.
            
            $correctWords = preg_split('/\s+/', $data['en'], -1, PREG_SPLIT_NO_EMPTY);
            $userWords = preg_split('/\s+/', $uTrans, -1, PREG_SPLIT_NO_EMPTY);
            
            $matchCount = 0;
            foreach ($userWords as $uw) {
                foreach ($correctWords as $cw) {
                    if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                        $matchCount++;
                        break; 
                    }
                }
            }
            
            $score = 0;
            if (count($correctWords) > 0) {
                $ratio = $matchCount / count($correctWords);
                $score = round($ratio * 10);
            }
            
            $formattedAnswer = $this->getDiffFeedback($userWords, $correctWords);

            $results[$idx] = [
                'user_answer' => $uTrans,
                'score' => $score,
                'formatted_answer' => $formattedAnswer,
                'correct_answer' => $data['en']
            ];
            
            $totalScore += $score;
        }

        // Fetch Paragraph
        $dbParagraph = \App\Models\GrammarQuestion::where('meeting_number', 13)
            ->where('section', 'paragraph')
            ->first();
        $paragraphEn = $dbParagraph ? $dbParagraph->correct_answer : $this->meeting13Paragraph['en'];

        $paraCorrectWords = preg_split('/\s+/', $paragraphEn, -1, PREG_SPLIT_NO_EMPTY);
        $paraUserWords = preg_split('/\s+/', $userParagraphAnswer, -1, PREG_SPLIT_NO_EMPTY);
        
        $paraMatchCount = 0;
        foreach ($paraUserWords as $uw) {
            foreach ($paraCorrectWords as $cw) {
                if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                    $paraMatchCount++;
                    break;
                }
            }
        }
        
        $paraScore = 0;
        if (count($paraCorrectWords) > 0) {
            $ratio = $paraMatchCount / count($paraCorrectWords);
            $paraScore = round($ratio * 20);
        }
        
        $paraFormatted = $this->getDiffFeedback($paraUserWords, $paraCorrectWords);
        $totalScore += $paraScore;
        
        $finalScore = round(($totalScore / $maxScore) * 100);

        session([
            'meeting13_submitted' => true,
            'meeting13_results' => $results,
            'meeting13_paragraph_result' => [
                'score' => $paraScore,
                'max_score' => 20,
                'formatted_answer' => $paraFormatted
            ],
            'meeting13_final_score' => $finalScore,
            'meeting13_user_answers' => $userAnswers,
            'meeting13_user_paragraph_answer' => $userParagraphAnswer
        ]);

        // Save score to database
        $this->saveMeetingScore(13, $finalScore);

        return redirect()->route('assignments.grammar-writing.meeting13');
    }

    public function meeting13Reset()
    {
        session()->forget([
            'meeting13_submitted', 
            'meeting13_results', 
            'meeting13_paragraph_result', 
            'meeting13_final_score', 
            'meeting13_user_answers', 
            'meeting13_user_paragraph_answer'
        ]);
        return redirect()->route('assignments.grammar-writing.meeting13');
    }

