    public function meeting14()
    {
        $submitted = session('meeting14_submitted', false);
        $results = session('meeting14_results', []);
        $paragraphResult = session('meeting14_paragraph_result', []);
        $finalScore = session('meeting14_final_score', 0);
        $userAnswers = session('meeting14_user_answers', []);
        $userParagraphAnswer = session('meeting14_user_paragraph_answer', '');

        // Fetch questions from DB
        $questions = \App\Models\GrammarQuestion::where('meeting_number', 14)
            ->where(function($q) {
                $q->whereNull('section')->orWhere('section', '!=', 'paragraph');
            })
            ->orderBy('question_number')
            ->get()
            ->map(function($q) {
                return [
                    'id' => $q->question_text,
                    'en' => $q->correct_answer,
                    'vocab' => $q->vocab,
                    'example' => [
                        'id' => $q->example_id,
                        'en' => $q->example_en
                    ],
                    'db_id' => $q->id
                ];
            });

        // Fetch Paragraph from DB
        $dbParagraph = \App\Models\GrammarQuestion::where('meeting_number', 14)
            ->where('section', 'paragraph')
            ->first();

        $fullParagraphId = $dbParagraph ? $dbParagraph->question_text : $this->meeting14Paragraph['id'];
        $fullParagraphEn = $dbParagraph ? $dbParagraph->correct_answer : $this->meeting14Paragraph['en'];
        $paragraphVocab = $dbParagraph ? $dbParagraph->vocab : $this->meeting14Paragraph['vocab'];
        $paragraphDbId = $dbParagraph ? $dbParagraph->id : null;

        return view('assignments.grammar-writing.meeting14', [
            'questions' => $questions,
            'fullParagraphId' => $fullParagraphId,
            'fullParagraphEn' => $fullParagraphEn,
            'paragraphVocab' => $paragraphVocab,
            'paragraphDbId' => $paragraphDbId,
            'submitted' => $submitted,
            'results' => $results,
            'paragraphResult' => $paragraphResult,
            'finalScore' => $finalScore,
            'userAnswers' => $userAnswers,
            'userParagraphAnswer' => $userParagraphAnswer
        ]);
    }

    public function meeting14Submit(Request $request)
    {
        $userAnswers = $request->input('userAnswers', []);
        $userParagraphAnswer = $request->input('userParagraphAnswer', '');
        
        // Fetch questions from DB for scoring
        $dbQuestions = \App\Models\GrammarQuestion::where('meeting_number', 14)
            ->where(function($q) {
                $q->whereNull('section')->orWhere('section', '!=', 'paragraph');
            })
            ->orderBy('question_number')
            ->get()
            ->map(function($q) {
                return [
                    'en' => $q->correct_answer
                ];
            });
        
        $results = [];
        $totalScore = 0;
        $maxScore = ($dbQuestions->count() * 10) + 20;

        foreach ($dbQuestions as $idx => $data) {
             // Adjust index to match DB (DB is 1-based, array logic in view might be 0-based or 1-based depending on usage)
            // View uses $idx from $questions which is collection, so 0-based index if iterated, but let's check view foreach
            // View: @foreach($questions as $idx => $data). If $questions is collection, idx is 0,1,2...
            // $userAnswers is array from form.
            // We should use $idx from loop.
            $uTrans = trim($userAnswers[$idx] ?? '');
            
            $correctWords = preg_split('/\s+/', $data['en'], -1, PREG_SPLIT_NO_EMPTY);
            $userWords = preg_split('/\s+/', $uTrans, -1, PREG_SPLIT_NO_EMPTY);
            
            $matchCount = 0;
            foreach ($userWords as $uw) {
                foreach ($correctWords as $cw) {
                    if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                        $matchCount++;
                        break; 
                    }
                }
            }
            
            $score = 0;
            if (count($correctWords) > 0) {
                $ratio = $matchCount / count($correctWords);
                $score = round($ratio * 10);
            }
            
            $formattedAnswer = $this->getDiffFeedback($userWords, $correctWords);

            $results[$idx] = [
                'user_answer' => $uTrans,
                'score' => $score,
                'formatted_answer' => $formattedAnswer,
                'correct_answer' => $data['en']
            ];
            
            $totalScore += $score;
        }

        // Fetch Paragraph
        $dbParagraph = \App\Models\GrammarQuestion::where('meeting_number', 14)
            ->where('section', 'paragraph')
            ->first();
        $paragraphEn = $dbParagraph ? $dbParagraph->correct_answer : $this->meeting14Paragraph['en'];

        $paraCorrectWords = preg_split('/\s+/', $paragraphEn, -1, PREG_SPLIT_NO_EMPTY);
        $paraUserWords = preg_split('/\s+/', $userParagraphAnswer, -1, PREG_SPLIT_NO_EMPTY);
        
        $paraMatchCount = 0;
        foreach ($paraUserWords as $uw) {
            foreach ($paraCorrectWords as $cw) {
                if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                    $paraMatchCount++;
                    break;
                }
            }
        }
        
        $paraScore = 0;
        if (count($paraCorrectWords) > 0) {
            $ratio = $paraMatchCount / count($paraCorrectWords);
            $paraScore = round($ratio * 20);
        }
        
        $paraFormatted = $this->getDiffFeedback($paraUserWords, $paraCorrectWords);
        $totalScore += $paraScore;
        
        $finalScore = round(($totalScore / $maxScore) * 100);

        session([
            'meeting14_submitted' => true,
            'meeting14_results' => $results,
            'meeting14_paragraph_result' => [
                'score' => $paraScore,
                'max_score' => 20,
                'formatted_answer' => $paraFormatted
            ],
            'meeting14_final_score' => $finalScore,
            'meeting14_user_answers' => $userAnswers,
            'meeting14_user_paragraph_answer' => $userParagraphAnswer
        ]);

        // Save score to database
        $this->saveMeetingScore(14, $finalScore);

        return redirect()->route('assignments.grammar-writing.meeting14');
    }

    public function meeting14Reset()
    {
        session()->forget([
            'meeting14_submitted', 
            'meeting14_results', 
            'meeting14_paragraph_result', 
            'meeting14_final_score', 
            'meeting14_user_answers', 
            'meeting14_user_paragraph_answer'
        ]);
        return redirect()->route('assignments.grammar-writing.meeting14');
    }

