    public function meeting15()
    {
        $submitted = session('meeting15_submitted', false);
        $results = session('meeting15_results', []);
        $paragraphResult = session('meeting15_paragraph_result', []);
        $finalScore = session('meeting15_final_score', 0);
        $userAnswers = session('meeting15_user_answers', []);
        $userParagraphAnswer = session('meeting15_user_paragraph_answer', '');

        // Fetch questions from DB
        $questions = \App\Models\GrammarQuestion::where('meeting_number', 15)
            ->where(function($q) {
                $q->whereNull('section')->orWhere('section', '!=', 'paragraph');
            })
            ->orderBy('question_number')
            ->get()
            ->map(function($q) {
                return [
                    'id' => $q->question_text,
                    'en' => $q->correct_answer,
                    'vocab' => $q->vocab,
                    'example' => [
                        'id' => $q->example_id,
                        'en' => $q->example_en
                    ],
                    'db_id' => $q->id
                ];
            });

        // Fetch Paragraph from DB
        $dbParagraph = \App\Models\GrammarQuestion::where('meeting_number', 15)
            ->where('section', 'paragraph')
            ->first();

        $fullParagraphId = $dbParagraph ? $dbParagraph->question_text : $this->meeting15Paragraph['id'];
        $fullParagraphEn = $dbParagraph ? $dbParagraph->correct_answer : $this->meeting15Paragraph['en'];
        $paragraphVocab = $dbParagraph ? $dbParagraph->vocab : $this->meeting15Paragraph['vocab'];
        $paragraphDbId = $dbParagraph ? $dbParagraph->id : null;

        return view('assignments.grammar-writing.meeting15', [
            'questions' => $questions,
            'fullParagraphId' => $fullParagraphId,
            'fullParagraphEn' => $fullParagraphEn,
            'paragraphVocab' => $paragraphVocab,
            'paragraphDbId' => $paragraphDbId,
            'submitted' => $submitted,
            'results' => $results,
            'paragraphResult' => $paragraphResult,
            'finalScore' => $finalScore,
            'userAnswers' => $userAnswers,
            'userParagraphAnswer' => $userParagraphAnswer
        ]);
    }

    public function meeting15Submit(Request $request)
    {
        $userAnswers = $request->input('userAnswers', []);
        $userParagraphAnswer = $request->input('userParagraphAnswer', '');
        
        // Fetch questions from DB for scoring
        $dbQuestions = \App\Models\GrammarQuestion::where('meeting_number', 15)
            ->where(function($q) {
                $q->whereNull('section')->orWhere('section', '!=', 'paragraph');
            })
            ->orderBy('question_number')
            ->get()
            ->map(function($q) {
                return [
                    'en' => $q->correct_answer
                ];
            });
        
        $results = [];
        $totalScore = 0;
        $maxScore = ($dbQuestions->count() * 10) + 20;

        foreach ($dbQuestions as $idx => $data) {
             // Adjust index to match use in view (loop counter vs key)
             // Typically $questions from DB is a collection.
             // If we iterate $dbQuestions as $idx => $data, idx is 0-based index.
             // View uses $questions as $idx => $data.
             // User answers are keyed by loop index (or meeting question number).
             // Since we order by question_number, the order is consistent.
            $uTrans = trim($userAnswers[$idx] ?? '');
            
            $correctWords = preg_split('/\s+/', $data['en'], -1, PREG_SPLIT_NO_EMPTY);
            $userWords = preg_split('/\s+/', $uTrans, -1, PREG_SPLIT_NO_EMPTY);
            
            $matchCount = 0;
            foreach ($userWords as $uw) {
                foreach ($correctWords as $cw) {
                    if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                        $matchCount++;
                        break; 
                    }
                }
            }
            
            $score = 0;
            if (count($correctWords) > 0) {
                $ratio = $matchCount / count($correctWords);
                $score = round($ratio * 10);
            }
            
            $formattedAnswer = $this->getDiffFeedback($userWords, $correctWords);

            $results[$idx] = [
                'user_answer' => $uTrans,
                'score' => $score,
                'formatted_answer' => $formattedAnswer,
                'correct_answer' => $data['en']
            ];
            
            $totalScore += $score;
        }

        // Fetch Paragraph
        $dbParagraph = \App\Models\GrammarQuestion::where('meeting_number', 15)
            ->where('section', 'paragraph')
            ->first();
        $paragraphEn = $dbParagraph ? $dbParagraph->correct_answer : $this->meeting15Paragraph['en'];

        $paraCorrectWords = preg_split('/\s+/', $paragraphEn, -1, PREG_SPLIT_NO_EMPTY);
        $paraUserWords = preg_split('/\s+/', $userParagraphAnswer, -1, PREG_SPLIT_NO_EMPTY);
        
        $paraMatchCount = 0;
        foreach ($paraUserWords as $uw) {
            foreach ($paraCorrectWords as $cw) {
                if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                    $paraMatchCount++;
                    break;
                }
            }
        }
        
        $paraScore = 0;
        if (count($paraCorrectWords) > 0) {
            $ratio = $paraMatchCount / count($paraCorrectWords);
            $paraScore = round($ratio * 20);
        }
        
        $paraFormatted = $this->getDiffFeedback($paraUserWords, $paraCorrectWords);
        $totalScore += $paraScore;
        
        $finalScore = round(($totalScore / $maxScore) * 100);

        session([
            'meeting15_submitted' => true,
            'meeting15_results' => $results,
            'meeting15_paragraph_result' => [
                'score' => $paraScore,
                'max_score' => 20,
                'formatted_answer' => $paraFormatted
            ],
            'meeting15_final_score' => $finalScore,
            'meeting15_user_answers' => $userAnswers,
            'meeting15_user_paragraph_answer' => $userParagraphAnswer
        ]);

        // Save score to database
        $this->saveMeetingScore(15, $finalScore);

        return redirect()->route('assignments.grammar-writing.meeting15');
    }

    public function meeting15Reset()
    {
        session()->forget([
            'meeting15_submitted', 
            'meeting15_results', 
            'meeting15_paragraph_result', 
            'meeting15_final_score', 
            'meeting15_user_answers', 
            'meeting15_user_paragraph_answer'
        ]);
        return redirect()->route('assignments.grammar-writing.meeting15');
    }

