    public function meeting17()
    {
        $submitted = session('meeting17_submitted', false);
        $results = session('meeting17_results', []);
        $paragraphResult = session('meeting17_paragraph_result', []);
        $finalScore = session('meeting17_final_score', 0);
        $userAnswers = session('meeting17_user_answers', []);
        $userParagraphAnswer = session('meeting17_user_paragraph_answer', '');

        // Fetch Questions from DB
        $dbQuestions = \App\Models\GrammarQuestion::where('meeting_number', 17)
            ->whereNull('section')
            ->orderBy('question_number')
            ->get();

        $questions = [];
        if ($dbQuestions->count() > 0) {
            foreach ($dbQuestions as $q) {
                $questions[$q->question_number] = [
                    'id' => $q->question_text,
                    'en' => $q->correct_answer,
                    'example' => [
                        'id' => $q->example_text ?? $q->example_id, // Handle if column name differs or just fallback
                        'en' => $q->example_en
                    ],
                    'vocab' => $q->vocab,
                    'db_id' => $q->id
                ];
                // Handle potential missing example data structure from migration
                if ($q->example_id) {
                     $questions[$q->question_number]['example']['id'] = $q->example_id;
                }
            }
        } else {
            // Fallback to array if DB is empty
            $questions = $this->meeting17Questions;
        }

        // Fetch Paragraph from DB
        $dbParagraph = \App\Models\GrammarQuestion::where('meeting_number', 17)
            ->where('section', 'paragraph')
            ->first();
            
        $fullParagraphId = $dbParagraph ? $dbParagraph->question_text : $this->meeting17Paragraph['id'];
        $fullParagraphEn = $dbParagraph ? $dbParagraph->correct_answer : $this->meeting17Paragraph['en'];
        $paragraphVocab = $dbParagraph ? $dbParagraph->vocab : $this->meeting17Paragraph['vocab'];
        $paragraphDbId = $dbParagraph ? $dbParagraph->id : null;

        // Shared example for Noun Clause
        $nounClauseExample = [
            'id' => 'Saya tidak tahu apakah dia akan datang.',
            'en' => 'I don\'t know whether he will come.'
        ];

        return view('assignments.grammar-writing.meeting17', [
            'questions' => $questions,
            'fullParagraphId' => $fullParagraphId,
            'fullParagraphEn' => $fullParagraphEn,
            'paragraphVocab' => $paragraphVocab,
            'paragraphDbId' => $paragraphDbId,
            'nounClauseExample' => $nounClauseExample,
            'submitted' => $submitted,
            'results' => $results,
            'paragraphResult' => $paragraphResult,
            'finalScore' => $finalScore,
            'userAnswers' => $userAnswers,
            'userParagraphAnswer' => $userParagraphAnswer
        ]);
    }

    public function meeting17Submit(Request $request)
    {
        $userAnswers = $request->input('userAnswers', []);
        $userParagraphAnswer = $request->input('userParagraphAnswer', '');
        
        // Fetch Questions from DB
        $dbQuestions = \App\Models\GrammarQuestion::where('meeting_number', 17)
            ->whereNull('section')
            ->orderBy('question_number')
            ->get();
            
        $questions = [];
        if ($dbQuestions->count() > 0) {
            foreach ($dbQuestions as $q) {
                $questions[$q->question_number] = [
                    'id' => $q->question_text,
                    'en' => $q->correct_answer
                ];
            }
        } else {
            $questions = $this->meeting17Questions;
        }

        // Fetch Paragraph from DB
        $dbParagraph = \App\Models\GrammarQuestion::where('meeting_number', 17)
            ->where('section', 'paragraph')
            ->first();
        $paragraphEn = $dbParagraph ? $dbParagraph->correct_answer : $this->meeting17Paragraph['en'];

        $results = [];
        $totalScore = 0;
        $maxScore = (count($questions) * 10) + 20;

        foreach ($questions as $idx => $data) {
            $uTrans = trim($userAnswers[$idx] ?? '');
            
            $correctWords = preg_split('/\s+/', $data['en'], -1, PREG_SPLIT_NO_EMPTY);
            $userWords = preg_split('/\s+/', $uTrans, -1, PREG_SPLIT_NO_EMPTY);
            
            $matchCount = 0;
            foreach ($userWords as $uw) {
                foreach ($correctWords as $cw) {
                    if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                        $matchCount++;
                        break; 
                    }
                }
            }
            
            $score = 0;
            if (count($correctWords) > 0) {
                $ratio = $matchCount / count($correctWords);
                $score = round($ratio * 10);
            }
            
            $formattedAnswer = $this->getDiffFeedback($userWords, $correctWords);

            $results[$idx] = [
                'user_answer' => $uTrans,
                'score' => $score,
                'formatted_answer' => $formattedAnswer,
                'correct_answer' => $data['en']
            ];
            
            $totalScore += $score;
        }

        $paraCorrectWords = preg_split('/\s+/', $paragraphEn, -1, PREG_SPLIT_NO_EMPTY);
        $paraUserWords = preg_split('/\s+/', $userParagraphAnswer, -1, PREG_SPLIT_NO_EMPTY);
        
        $paraMatchCount = 0;
        foreach ($paraUserWords as $uw) {
            foreach ($paraCorrectWords as $cw) {
                if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                    $paraMatchCount++;
                    break;
                }
            }
        }
        
        $paraScore = 0;
        if (count($paraCorrectWords) > 0) {
            $ratio = $paraMatchCount / count($paraCorrectWords);
            $paraScore = round($ratio * 20);
        }
        
$paraFormatted = $this->getDiffFeedback($paraUserWords, $paraCorrectWords);
        $totalScore += $paraScore;
        
        $finalScore = round(($totalScore / $maxScore) * 100);

        session([
            'meeting17_submitted' => true,
            'meeting17_results' => $results,
            'meeting17_paragraph_result' => [
                'score' => $paraScore,
                'max_score' => 20,
                'formatted_answer' => $paraFormatted
            ],
            'meeting17_final_score' => $finalScore,
            'meeting17_user_answers' => $userAnswers,
            'meeting17_user_paragraph_answer' => $userParagraphAnswer
        ]);

        // Save score to database
        $this->saveMeetingScore(17, $finalScore);

        return redirect()->route('assignments.grammar-writing.meeting17');
    }

