    public function meeting16Submit(Request $request)
    {
        $userParagraphAnswer = $request->input('userParagraphAnswer');
        
        // Fetch Paragraph from DB
        $dbParagraph = \App\Models\GrammarQuestion::where('meeting_number', 16)
            ->where('section', 'paragraph')
            ->first();
        $paragraphEn = $dbParagraph ? $dbParagraph->correct_answer : $this->meeting16Paragraph['en'];
        
        // Split Correct and User Paragraphs into words
        $paraCorrectWords = preg_split('/\s+/', $paragraphEn, -1, PREG_SPLIT_NO_EMPTY);
        $paraUserWords = preg_split('/\s+/', $userParagraphAnswer, -1, PREG_SPLIT_NO_EMPTY);
        
        // Calculate Matches (Rough Logic: word exists in correct array)
        $paraMatchCount = 0;
        foreach ($paraUserWords as $uw) {
            foreach ($paraCorrectWords as $cw) {
                // simple case-insensitive comparison, ignoring some punctuation
                if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                    $paraMatchCount++;
                    break;
                }
            }
        }
        
        // Score Calculation
        $paraScore = 0;
        if (count($paraCorrectWords) > 0) {
            $ratio = $paraMatchCount / count($paraCorrectWords);
            $paraScore = round($ratio * 100); // Only paragraph: Max 100
        }
        
        // Generate formatting
        $paraFormatted = $this->getDiffFeedback($paraUserWords, $paraCorrectWords);
        
        $finalScore = $paraScore; // Since there are no other questions

        session([
            'meeting16_submitted' => true,
            'meeting16_results' => [], // No individual question results
            'meeting16_paragraph_result' => [
                'score' => $paraScore,
                'max_score' => 100, // Adjusted max score to 100 since it is the only task
                'formatted_answer' => $paraFormatted
            ],
            'meeting16_final_score' => $finalScore,
            'meeting16_user_answers' => [],
            'meeting16_user_paragraph_answer' => $userParagraphAnswer
        ]);

        // Save score to database
        $this->saveMeetingScore(16, $finalScore);

        return redirect()->route('assignments.grammar-writing.meeting16');
    }

