    public function meeting18()
    {
        $submitted = session('meeting18_submitted', false);
        $results = session('meeting18_results', []);
        $paragraphResult = session('meeting18_paragraph_result', []);
        $finalScore = session('meeting18_final_score', 0);
        $userAnswers = session('meeting18_user_answers', []);
        $userParagraphAnswer = session('meeting18_user_paragraph_answer', '');

        // Fetch questions from database
        $dbQuestions = \App\Models\GrammarQuestion::where('meeting_number', 18)
            ->whereNull('section')
            ->orderBy('question_number')
            ->get();

        $questions = [];
        if ($dbQuestions->count() > 0) {
            foreach ($dbQuestions as $q) {
                $questions[$q->question_number] = [
                    'id' => $q->question_text,
                    'en' => $q->correct_answer,
                    'vocab' => $q->vocab,
                    'example' => [
                        'id' => $q->example_id,
                        'en' => $q->example_en
                    ],
                    'db_id' => $q->id
                ];
            }
        } else {
            $questions = $this->meeting18Questions;
        }

        // Fetch paragraph from database
        $dbParagraph = \App\Models\GrammarQuestion::where('meeting_number', 18)
            ->where('section', 'paragraph')
            ->first();

        if ($dbParagraph) {
            $fullParagraphId = $dbParagraph->question_text;
            $fullParagraphEn = $dbParagraph->correct_answer;
            $paragraphVocab = $dbParagraph->vocab;
            $paragraphDbId = $dbParagraph->id;
        } else {
            $fullParagraphId = $this->meeting18Paragraph['id'];
            $fullParagraphEn = $this->meeting18Paragraph['en'];
            $paragraphVocab = $this->meeting18Paragraph['vocab'];
            $paragraphDbId = null;
        }

        // Shared example for Reducing/Participle
        $reducingExample = [
            'id' => 'Orang yang sedang berjalan di taman adalah guru saya.',
            'en' => 'The person walking in the park is my teacher.'
        ];

        return view('assignments.grammar-writing.meeting18', [
            'questions' => $questions,
            'fullParagraphId' => $fullParagraphId,
            'fullParagraphEn' => $fullParagraphEn,
            'paragraphVocab' => $paragraphVocab,
            'paragraphDbId' => $paragraphDbId,
            'reducingExample' => $reducingExample,
            'submitted' => $submitted,
            'results' => $results,
            'paragraphResult' => $paragraphResult,
            'finalScore' => $finalScore,
            'userAnswers' => $userAnswers,
            'userParagraphAnswer' => $userParagraphAnswer
        ]);
    }

    public function meeting18Submit(Request $request)
    {
        $userAnswers = $request->input('userAnswers', []);
        $userParagraphAnswer = $request->input('userParagraphAnswer', '');
        
        // Fetch questions from database
        $dbQuestions = \App\Models\GrammarQuestion::where('meeting_number', 18)
            ->whereNull('section')
            ->orderBy('question_number')
            ->get();

        $questions = [];
        if ($dbQuestions->count() > 0) {
            foreach ($dbQuestions as $q) {
                $questions[$q->question_number] = [
                    'id' => $q->question_text,
                    'en' => $q->correct_answer,
                ];
            }
        } else {
            $questions = $this->meeting18Questions;
        }

        $results = [];
        $totalScore = 0;
        $maxScore = (count($questions) * 10) + 20;

        foreach ($questions as $idx => $data) {
            $uTrans = trim($userAnswers[$idx] ?? '');
            
            $correctWords = preg_split('/\s+/', $data['en'], -1, PREG_SPLIT_NO_EMPTY);
            $userWords = preg_split('/\s+/', $uTrans, -1, PREG_SPLIT_NO_EMPTY);
            
            $matchCount = 0;
            foreach ($userWords as $uw) {
                foreach ($correctWords as $cw) {
                    if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                        $matchCount++;
                        break; 
                    }
                }
            }
            
            $score = 0;
            if (count($correctWords) > 0) {
                $ratio = $matchCount / count($correctWords);
                $score = round($ratio * 10);
            }
            
            $formattedAnswer = $this->getDiffFeedback($userWords, $correctWords);

            $results[$idx] = [
                'user_answer' => $uTrans,
                'score' => $score,
                'formatted_answer' => $formattedAnswer,
                'correct_answer' => $data['en']
            ];
            
            $totalScore += $score;
        }

        // Fetch paragraph
        $dbParagraph = \App\Models\GrammarQuestion::where('meeting_number', 18)
            ->where('section', 'paragraph')
            ->first();
        $paragraphEn = $dbParagraph ? $dbParagraph->correct_answer : $this->meeting18Paragraph['en'];

        $paraCorrectWords = preg_split('/\s+/', $paragraphEn, -1, PREG_SPLIT_NO_EMPTY);
        $paraUserWords = preg_split('/\s+/', $userParagraphAnswer, -1, PREG_SPLIT_NO_EMPTY);
        
        $paraMatchCount = 0;
        foreach ($paraUserWords as $uw) {
            foreach ($paraCorrectWords as $cw) {
                if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                    $paraMatchCount++;
                    break;
                }
            }
        }
        
        $paraScore = 0;
        if (count($paraCorrectWords) > 0) {
            $ratio = $paraMatchCount / count($paraCorrectWords);
            $paraScore = round($ratio * 20);
        }
        
        $paraFormatted = $this->getDiffFeedback($paraUserWords, $paraCorrectWords);
        $totalScore += $paraScore;
        
        $finalScore = round(($totalScore / $maxScore) * 100);

        session([
            'meeting18_submitted' => true,
            'meeting18_results' => $results,
            'meeting18_paragraph_result' => [
                'score' => $paraScore,
                'max_score' => 20,
                'formatted_answer' => $paraFormatted
            ],
            'meeting18_final_score' => $finalScore,
            'meeting18_user_answers' => $userAnswers,
            'meeting18_user_paragraph_answer' => $userParagraphAnswer
        ]);

        // Save score to database
        $this->saveMeetingScore(18, $finalScore);

        return redirect()->route('assignments.grammar-writing.meeting18');
    }

    public function meeting18Reset()
    {
        session()->forget([
            'meeting18_submitted', 
            'meeting18_results', 
            'meeting18_paragraph_result', 
            'meeting18_final_score', 
            'meeting18_user_answers', 
            'meeting18_user_paragraph_answer'
        ]);
        return redirect()->route('assignments.grammar-writing.meeting18');
    }

    public function meeting4(Request $request)

    {
        $submitted = session('meeting4_submitted', false);
        $results = session('meeting4_results', []);
        $paragraphResult = session('meeting4_paragraph_result', []);
        $finalScore = session('meeting4_final_score', 0);
        $userAnswers = session('meeting4_user_answers', []);
        $userParagraphAnswer = session('meeting4_user_paragraph_answer', '');

        $hasSectionColumn = $this->grammarQuestionsHasSectionColumn();

        $questionsQuery = \App\Models\GrammarQuestion::where('meeting_number', 4)
            ->orderBy('question_number');
        if ($hasSectionColumn) {
            $questionsQuery->where(function ($q) {
                $q->whereNull('section')
                    ->orWhere('section', '!=', 'paragraph');
            });
        }

        $dbQuestions = $questionsQuery->get()->filter(function ($q) use ($hasSectionColumn) {
            return $hasSectionColumn || (int) $q->question_number !== 999;
        })->values();

        $questions = $dbQuestions->isNotEmpty()
            ? $dbQuestions->mapWithKeys(function ($q) {
                return [$q->question_number => [
                    'id' => $q->question_text,
                    'en' => $q->correct_answer,
                    'vocab' => is_array($q->vocab) ? $q->vocab : [],
                    'db_id' => $q->id,
                ]];
            })->toArray()
            : $this->meeting4Questions;

        $paragraphQuery = \App\Models\GrammarQuestion::where('meeting_number', 4);
        if ($hasSectionColumn) {
            $paragraphQuery->where('section', 'paragraph');
        } else {
            $paragraphQuery->where('question_number', 999);
        }
        $dbParagraph = $paragraphQuery->first();
        $paragraphData = $dbParagraph
            ? [
                'id' => $dbParagraph->question_text,
                'en' => $dbParagraph->correct_answer,
                'sentences' => [],
                'vocab' => is_array($dbParagraph->vocab) ? $dbParagraph->vocab : [],
            ]
            : $this->meeting4Paragraph;

        return view('assignments.grammar-writing.meeting4', [
            'questions' => $questions,
            'fullParagraphId' => $paragraphData['id'],
            'fullParagraphEn' => $paragraphData['en'],
            'paragraphSentences' => $paragraphData['sentences'],
            'paragraphVocab' => $paragraphData['vocab'] ?? [],
            'submitted' => $submitted,
            'results' => $results,
            'paragraphResult' => $paragraphResult,
            'finalScore' => $finalScore,
            'userAnswers' => $userAnswers,
            'userParagraphAnswer' => $userParagraphAnswer
        ]);
    }

    public function meeting4Submit(Request $request)
    {
        $userAnswers = $request->input('userAnswers', []);
        $userParagraphAnswer = $request->input('userParagraphAnswer', '');

        $hasSectionColumn = $this->grammarQuestionsHasSectionColumn();

        $questionsQuery = \App\Models\GrammarQuestion::where('meeting_number', 4)
            ->orderBy('question_number');
        if ($hasSectionColumn) {
            $questionsQuery->where(function ($q) {
                $q->whereNull('section')
                    ->orWhere('section', '!=', 'paragraph');
            });
        }

        $dbQuestions = $questionsQuery->get()->filter(function ($q) use ($hasSectionColumn) {
            return $hasSectionColumn || (int) $q->question_number !== 999;
        })->values();

        $questions = $dbQuestions->isNotEmpty()
            ? $dbQuestions->mapWithKeys(function ($q) {
                return [$q->question_number => [
                    'id' => $q->question_text,
                    'en' => $q->correct_answer,
                    'vocab' => is_array($q->vocab) ? $q->vocab : [],
                ]];
            })->toArray()
            : $this->meeting4Questions;

        $paragraphQuery = \App\Models\GrammarQuestion::where('meeting_number', 4);
        if ($hasSectionColumn) {
            $paragraphQuery->where('section', 'paragraph');
        } else {
            $paragraphQuery->where('question_number', 999);
        }
        $dbParagraph = $paragraphQuery->first();
        $paragraphReference = $dbParagraph
            ? ['en' => $dbParagraph->correct_answer]
            : $this->meeting4Paragraph;
        
        $results = [];
        $totalScore = 0;
        $maxScore = (count($questions) * 10) + 20; // 10 points per question + 20 for paragraph

        // Check Questions
        foreach ($questions as $idx => $data) {
            $uTrans = trim($userAnswers[$idx]['trans'] ?? '');
            
            // Score Translation (10 points per question)
            $correctWords = preg_split('/\s+/', $data['en'], -1, PREG_SPLIT_NO_EMPTY);
            $userWords = preg_split('/\s+/', $uTrans, -1, PREG_SPLIT_NO_EMPTY);
            
            $matchCount = 0;
            foreach ($userWords as $uw) {
                foreach ($correctWords as $cw) {
                    if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                        $matchCount++;
                        break; 
                    }
                }
            }
            
            $transScore = 0;
            if (count($correctWords) > 0) {
                $ratio = $matchCount / count($correctWords);
                $transScore = round($ratio * 10); // Changed from 5 to 10
            }
            
            // Generate Diff Feedback
            $formattedAnswer = $this->getDiffFeedback($userWords, $correctWords);

            $results[$idx] = [
                'user_trans' => $uTrans,
                'trans_score' => $transScore,
                'formatted_answer' => $formattedAnswer
            ];
            
            $totalScore += $transScore;
        }

        // Check Paragraph
        $paraCorrectWords = preg_split('/\s+/', $paragraphReference['en'], -1, PREG_SPLIT_NO_EMPTY);
        $paraUserWords = preg_split('/\s+/', $userParagraphAnswer, -1, PREG_SPLIT_NO_EMPTY);
        
        $paraMatchCount = 0;
        foreach ($paraUserWords as $uw) {
            foreach ($paraCorrectWords as $cw) {
                if (strtolower(rtrim($uw, '.!,')) === strtolower(rtrim($cw, '.!,'))) {
                    $paraMatchCount++;
                    break;
                }
            }
        }
        
        $paraScore = 0;
        if (count($paraCorrectWords) > 0) {
            $ratio = $paraMatchCount / count($paraCorrectWords);
            $paraScore = round($ratio * 20);
        }
        
        $paraFormatted = $this->getDiffFeedback($paraUserWords, $paraCorrectWords);
        $totalScore += $paraScore;
        
        // Normalize to 100
        $finalScore = round(($totalScore / $maxScore) * 100);

        session([
            'meeting4_submitted' => true,
            'meeting4_results' => $results,
            'meeting4_paragraph_result' => [
                'score' => $paraScore,
                'max_score' => 20,
                'formatted_answer' => $paraFormatted
            ],
            'meeting4_final_score' => $finalScore,
            'meeting4_user_answers' => $userAnswers,
            'meeting4_user_paragraph_answer' => $userParagraphAnswer
        ]);

        // Save score to database
        $this->saveMeetingScore(4, $finalScore);

        return redirect()->route('assignments.grammar-writing.meeting4');
    }

