        $paragraphResult = session('meeting19_paragraph_result', []);
        $finalScore = session('meeting19_final_score', 0);
        $userAnswers = session('meeting19_user_answers', []);
        $userParagraphAnswer = session('meeting19_user_paragraph_answer', '');

        // Fetch Questions from DB
        $dbQuestions = \App\Models\GrammarQuestion::where('meeting_number', 19)
            ->whereNull('section')
            ->orderBy('question_number')
            ->get();

        $questions = [];
        if ($dbQuestions->count() > 0) {
            foreach ($dbQuestions as $q) {
                // Determine type/adverb from vocab (migration stored them there)
                $type = $q->vocab['_type'] ?? '';
                $adverb = $q->vocab['_adverb'] ?? '';
                
                $questions[$q->question_number] = [
                    'id' => $q->question_text,
                    'en' => $q->correct_answer,
                    'vocab' => $q->vocab,
                    'example' => [
                        'id' => $q->example_id,
                        'en' => $q->example_en
                    ],
                    'db_id' => $q->id,
                    'type' => $type,
                    'adverb' => $adverb
                ];
            }
        } else {
            $questions = $this->meeting19Questions;
        }

        // Fetch Paragraph from DB
        $dbParagraph = \App\Models\GrammarQuestion::where('meeting_number', 19)
            ->where('section', 'paragraph')
            ->first();

        if ($dbParagraph) {
            $fullParagraphId = $dbParagraph->question_text;
            $fullParagraphEn = $dbParagraph->correct_answer;
            $paragraphVocab = $dbParagraph->vocab;
            $paragraphDbId = $dbParagraph->id;
        } else {
            $fullParagraphId = $this->meeting19Paragraph['id'];
            $fullParagraphEn = $this->meeting19Paragraph['en'];
            $paragraphVocab = $this->meeting19Paragraph['vocab'];
            $paragraphDbId = null;
        }

        return view('assignments.grammar-writing.meeting19', [
