    public function meeting20Submit(Request $request)
    {
        $userParagraphAnswer = $request->input('userParagraphAnswer', '');
        
        // Fetch Paragraph from DB
        $dbParagraph = \App\Models\GrammarQuestion::where('meeting_number', 20)
            ->where('section', 'paragraph')
            ->first();
        $fullParagraphEn = $dbParagraph ? $dbParagraph->correct_answer : $this->meeting20Paragraph['en'];
        
        // Calculate score
        $paraCorrectWords = preg_split('/\s+/', $fullParagraphEn, -1, PREG_SPLIT_NO_EMPTY);
        $paraUserWords = preg_split('/\s+/', $userParagraphAnswer, -1, PREG_SPLIT_NO_EMPTY);
        
        $paraMatchCount = 0;
        foreach ($paraUserWords as $uw) {
            foreach ($paraCorrectWords as $cw) {
                if (strtolower(rtrim($uw, '.,!')) === strtolower(rtrim($cw, '.,!'))) {
                    $paraMatchCount++;
                    break;
                }
            }
        }
        
        $paragraphScore = 0;
        if (count($paraCorrectWords) > 0) {
            $ratio = $paraMatchCount / count($paraCorrectWords);
            $paragraphScore = round($ratio * 100);
        }
        
        $formattedAnswer = $this->getDiffFeedback($paraUserWords, $paraCorrectWords);
        
        $paragraphResult = [
            'score' => $paragraphScore,
            'max_score' => 100,
            'formatted_answer' => $formattedAnswer
        ];
        
        session([
            'meeting20_submitted' => true,
            'meeting20_user_paragraph_answer' => $userParagraphAnswer,
            'meeting20_paragraph_result' => $paragraphResult,
            'meeting20_final_score' => $paragraphScore
        ]);

        // Save score to database
        $this->saveMeetingScore(20, $paragraphScore);

        return redirect()->route('assignments.grammar-writing.meeting20');
    }

    private function srtTimeToSeconds($srtTime)
    {
        // Normalize decimal separator
        $srtTime = str_replace(',', '.', $srtTime);
        
        $ms = 0;
        if (strpos($srtTime, '.') !== false) {
            list($time, $msPart) = explode('.', $srtTime);
            $ms = "0." . $msPart;
        } else {
            $time = $srtTime;
        }
        
        $parts = explode(':', $time);
        $count = count($parts);
        
        $h = 0; $m = 0; $s = 0;
        
        if ($count === 3) {
            list($h, $m, $s) = $parts;
        } elseif ($count === 2) {
            list($m, $s) = $parts;
        } else {
            $s = $parts[0];
        }
        
        return ($h * 3600) + ($m * 60) + $s + (float)$ms;
    }


