    /**
     * Helper method to save meeting score to database
     */
    private function saveMeetingScore($meetingNumber, $score)
    {
        MeetingScore::updateOrCreate(
            [
                'user_id' => Auth::id(),
                'meeting_number' => $meetingNumber
            ],
            [
                'score' => $score,
                'submitted_at' => now()
            ]
        );
    }
